/* Déclic — Anglais B1 (unités 4 à 6). Format : docs/ANGLAIS.md */
(()=>{
// X : toutes les combinaisons de morceaux de phrase (variantes de réponse)
const X=(...a)=>a.reduce((acc,p)=>acc.flatMap(s=>[].concat(p).map(t=>s+t)),['']);
// V : ajoute les formes contractées ambiguës (’d = would, ’s = is), que la correction ne développe pas
const PD=/\b(I|[Yy]ou|[Hh]e|[Ss]he|[Ii]t|[Ww]e|[Tt]hey)[’']d\b/g, PS=/\b([Ii]t|[Hh]e|[Ss]he|[Tt]hat|[Tt]here|[Ww]hat|[Ww]ho|[Hh]ere)[’']s\b/g;
const V=(...lists)=>{ const out=new Set(); lists.flat().forEach(s=>{
  const b=s.replace(PD,'$1 would').replace(PS,'$1 is');
  const d=t=>t.replace(/\b(I|[Yy]ou|[Hh]e|[Ss]he|[Ii]t|[Ww]e|[Tt]hey) would\b/g,'$1’d'), z=t=>t.replace(/\b([Ii]t|[Hh]e|[Ss]he|[Tt]hat|[Tt]here|[Ww]hat|[Ww]ho|[Hh]ere) is\b/g,'$1’s');
  [b,d(b),z(b),d(z(b))].forEach(x=>out.add(x)); }); return [...out]; };

COURS.push(
/* ===================== 4. The future ===================== */
{subj:'en', sem:'b1', id:'en-b1-future', o:4, h:'The future', p:'Parler de l’avenir avec précision : intentions, rendez-vous, décisions prises sur le moment, actions en cours dans le futur et degrés de probabilité.', steps:[
 {kind:'Écoute', h:'Big news',
  p:`<p>By the end of this unit, you will be able to talk about your plans, arrangements and predictions, say what you will be doing at a given moment in the future, and say how likely something is.</p>
<p>Maya has some big news for her friend Josh. <b>Listen without reading</b>, twice if you like, then answer. The text will appear after your answer.</p>
<p><b>Question:</b> when does Maya start her new job?</p>`,
  audio:[['Josh','So, is it true? Are you really leaving London?'],['Maya','It is! I’m starting a new job in Edinburgh on the third of March. I signed the contract yesterday.'],['Josh','Wow, congratulations! What are you going to do about your flat?'],['Maya','I’m going to tell my landlord tomorrow that I’m moving out. And I’m flying up to Edinburgh on Friday to look at a few places.'],['Josh','Edinburgh’s beautiful, but it’s bound to be colder than here. You’ll need a proper coat.'],['Maya','I know! On the other hand, rents there are likely to be lower, so I might finally have a spare room.'],['Josh','Then I’ll definitely come and visit.'],['Maya','You’d better! Honestly, I can’t believe it. This time next month, I’ll be packing boxes.'],['Josh','Do you need a hand with the move? I’ll help you, I promise. I won’t let you carry everything on your own.'],['Maya','That’s really kind. I’ll probably take you up on that.']], cache:true,
  opts:['On Friday','On 3 March','On 13 March','Next year'], ans:1,
  why:'Maya dit <i lang="en">I’m starting a new job in Edinburgh on the third of March</i> : le 3 mars. Vendredi, elle va seulement visiter des appartements (<i lang="en">I’m flying up to Edinburgh on Friday to look at a few places</i>). Remarque qu’elle utilise le présent continu pour deux projets déjà organisés.'},

 {kind:'Vocabulaire', h:'Plans and life changes',
  p:`<p>Here are useful phrases from the dialogue, and a few more. Tap a line to hear it, then repeat it aloud. Learn each one as a whole phrase: the small words (<i lang="en">to, out, up, in, on</i>) are part of the meaning. They will come back in your vocabulary review.</p>`,
  mots:[['to move to (a city)','déménager à','We’re moving to Bristol in June.'],['to move out','quitter son logement','I’m moving out at the end of the month.'],['to sign a contract','signer un contrat','She signed the contract yesterday.'],['to hand in your notice','donner sa démission','He’s going to hand in his notice on Monday.'],['to settle in','s’installer, prendre ses marques','It took me a few weeks to settle in.'],['to look forward to (doing)','avoir hâte de','I’m looking forward to seeing you.'],['to give somebody a hand','donner un coup de main','Can you give me a hand with these boxes?'],['to take somebody up on (an offer)','accepter (une proposition)','Thanks, I might take you up on that.'],['this time next week','la semaine prochaine à cette heure-ci','This time next week, I’ll be lying on a beach.'],['in the near future','dans un avenir proche','Prices will go up in the near future.'],['sooner or later','tôt ou tard','Sooner or later, you’ll have to decide.'],['in the long run','à long terme','Buying a good coat is cheaper in the long run.']],
  note:'<b>Attention :</b> dans <i lang="en">look forward to</i>, <i lang="en">to</i> est une préposition, donc il est suivi d’un nom ou d’un verbe en <b>-ing</b> : <i lang="en">I’m looking forward to seeing you</i>, jamais « to see you ». Et « donner sa démission » se dit <i lang="en">hand in your notice</i>, pas « give your demission ».'},

 {kind:'Vocabulaire', h:'How likely is it?',
  p:`<p>To talk about the future, you also need to say <b>how sure</b> you are. Tap each line to hear it. Notice the structure that follows each phrase (<i lang="en">to + verb</i>, or a full sentence).</p>`,
  mots:[['to be bound to (do)','ne pas manquer de, être sûr de','It’s bound to rain in Scotland.'],['to be likely to (do)','avoir de fortes chances de, risquer de','Prices are likely to rise.'],['to be unlikely to (do)','avoir peu de chances de','He’s unlikely to arrive on time.'],['there’s a good chance (that)','il y a de fortes chances que','There’s a good chance that we’ll win.'],['I doubt (that)','je doute que','I doubt she’ll call back.'],['definitely','sans aucun doute','I’ll definitely be there.'],['probably','probablement','We’ll probably leave early.'],['up in the air','pas encore décidé, en suspens','Our holiday plans are still up in the air.']],
  note:'<i lang="en">likely</i> ressemble à un adverbe à cause de <i>-ly</i>, mais c’est un <b>adjectif</b> : <i lang="en">It’s likely to rain</i> (il risque de pleuvoir), <i lang="en">a likely result</i> (un résultat probable).'},

 {kind:'Pratique', h:'Recall: bound to',
  p:'Translate into English. Use <i lang="en">bound to</i>.<br>« Elle sera forcément en retard. »', lab:'Your sentence', txt:V(['She is bound to be late.','She’s definitely bound to be late.']),
  why:'<i lang="en">She’s bound to be late</i> : <i lang="en">be bound to</i> + base verbale exprime une quasi-certitude, souvent fondée sur l’expérience (elle est toujours en retard).'},

 {kind:'Grammaire', h:'Will, going to ou présent continu ?',
  p:`<p>En français, on dit « je pars demain », « je vais partir » ou « je partirai » presque sans différence. En anglais, le choix dépend surtout d’une question : <b>quand la décision a-t-elle été prise, et sur quoi repose la prédiction&nbsp;?</b> Dans le dialogue, Maya utilise trois formes en quelques secondes.</p>
<div class="def"><ul><li><b>be going to + base verbale</b> : une <b>intention</b> déjà décidée (<i lang="en">I’m going to tell my landlord tomorrow</i>), ou une prédiction fondée sur ce qu’on voit (<i lang="en">Look at the sky: it’s going to rain</i>).</li><li><b>présent continu</b> : un <b>arrangement</b> déjà organisé, souvent avec un jour, une heure, une autre personne, un billet (<i lang="en">I’m flying to Edinburgh on Friday</i>).</li><li><b>will + base verbale</b> : une décision prise <b>au moment où l’on parle</b>, une offre, une promesse (<i lang="en">I’ll help you, I promise</i>), ou une prédiction qui est une opinion (<i lang="en">You’ll love it</i>, <i lang="en">I think it’ll be fine</i>).</li><li><b>présent simple</b> : un horaire ou un programme officiel (<i lang="en">The train leaves at 7.40. The course starts on Monday.</i>).</li></ul></div>
<div class="idea"><p>Pense à une ligne du temps. Si la décision existe <b>avant</b> la conversation, c’est <i lang="en">going to</i> (intention) ou le présent continu (c’est déjà organisé). Si elle naît <b>pendant</b> la conversation, c’est <i lang="en">will</i>. Entre <i lang="en">going to</i> et le présent continu, la différence est souvent faible : <i lang="en">I’m going to see Tom tonight</i> et <i lang="en">I’m seeing Tom tonight</i> sont corrects tous les deux ; le second insiste sur le rendez-vous fixé.</p></div>
<div class="ex"><p><i lang="en">– The phone’s ringing! – I’ll get it.</i> (décision sur le moment)<br><i lang="en">I’m going to learn to drive this year.</i> (intention)<br><i lang="en">We’re having dinner with Sara on Saturday.</i> (rendez-vous)</p></div>
<div class="warn"><p>Trois pièges des francophones. 1) Le présent français pour le futur : « Demain je vais à Londres » ne se dit pas <i lang="en">Tomorrow I go to London</i>, mais <i lang="en">I’m going to London tomorrow</i>. 2) Après <b>when, as soon as, before, after, until, if</b>, l’anglais met le <b>présent</b>, jamais <i lang="en">will</i> : <i lang="en">I’ll call you when I <b>arrive</b></i>, alors que le français dit « quand j’arriverai ». 3) « Je vais t’aider » se dit <i lang="en">I’ll help you</i> si tu le décides sur le moment : le « je vais » français n’est pas toujours <i lang="en">going to</i>.</p></div>`,
  audio:'The phone’s ringing! I’ll get it. I’m going to learn to drive this year. We’re having dinner with Sara on Saturday. The train leaves at seven forty.'},

 {kind:'Méthode', h:'Choisir la bonne forme du futur',
  p:`<p><b>Quand :</b> chaque fois que tu parles d’une action future et que tu hésites entre plusieurs formes. <b>Pourquoi ça marche :</b> chaque forme correspond à un type d’information (horaire, rendez-vous, intention, décision sur le moment) ; il suffit d’identifier lequel. <b>Comment :</b> pose-toi ces questions dans l’ordre.</p>
<ol><li>Le verbe suit-il <i lang="en">when, as soon as, before, after, until, if</i>&nbsp;? → <b>présent</b>.</li><li>Est-ce un horaire, un programme officiel&nbsp;? → <b>présent simple</b>.</li><li>Est-ce déjà organisé (date, heure, réservation, autre personne)&nbsp;? → <b>présent continu</b>.</li><li>Est-ce une intention décidée avant, ou une prédiction fondée sur un indice visible&nbsp;? → <b>going to</b>.</li><li>Est-ce une décision prise maintenant, une offre, une promesse, une opinion sur l’avenir&nbsp;? → <b>will</b>.</li></ol>`,
  demo:{enonce:'Complète avec la bonne forme du verbe : (1) <i lang="en">– There’s no milk left. – Really? I ___ (buy) some.</i> (2) <i lang="en">I ___ (see) the dentist at 4.30 tomorrow, it’s in my diary.</i> (3) <i lang="en">Hurry up! The film ___ (start) at eight.</i> (4) <i lang="en">Text me when you ___ (get) home.</i>',
   etapes:[{f:'(1) <i lang="en">I’ll buy some.</i>',w:'La décision naît à l’instant où l’on apprend qu’il n’y a plus de lait : <i lang="en">will</i>. Avec <i lang="en">I’m going to buy some</i>, on dirait que c’était déjà prévu.'},
    {f:'(2) <i lang="en">I’m seeing the dentist at 4.30 tomorrow.</i>',w:'C’est un rendez-vous noté dans l’agenda, avec une heure : présent continu.'},
    {f:'(3) <i lang="en">The film starts at eight.</i>',w:'C’est l’horaire du cinéma, qui ne dépend pas de nous : présent simple.'},
    {f:'(4) <i lang="en">Text me when you get home.</i>',w:'Après <i lang="en">when</i>, le futur s’exprime au présent : jamais « when you will get ».'}],
   conclusion:'<i lang="en">I’ll buy some. I’m seeing the dentist at 4.30 tomorrow. The film starts at eight. Text me when you get home.</i>'}},

 {kind:'Pratique', h:'Practice: an arrangement',
  p:'Complete with the best future form of the verb in brackets. Write the missing words only.<br><i lang="en">I can’t come to the meeting on Friday. I ___ (fly) to Berlin: my tickets are booked.</i>', lab:'Missing words', txt:['am flying','I am flying','am going to fly','I am going to fly'],
  why:'Les billets sont réservés : c’est un arrangement, donc le présent continu est le plus naturel, <i lang="en">I’m flying to Berlin</i>. <i lang="en">I’m going to fly</i> est aussi correct (intention). <i lang="en">I will fly</i> sonnerait comme une décision prise à l’instant.'},

 {kind:'Pratique', h:'Practice: an offer',
  p:'Your neighbour says: <i lang="en">These shopping bags are so heavy!</i> You offer to help. Translate into English.<br>« Je vais vous aider : je vais porter celui-ci. »', lab:'Your answer', txt:X(['I will help you','I will give you a hand','Let me help you'],'. ',['I will carry this one.','I will take this one.']),
  why:'Une offre faite sur le moment se dit avec <i lang="en">will</i> : <i lang="en">I’ll help you. I’ll carry this one.</i> Le « je vais » français trompe : <i lang="en">I’m going to help you</i> sonnerait comme un projet décidé à l’avance.'},

 {kind:'Pratique', h:'Practice: after as soon as',
  p:'Translate into English. Be careful with the verb after <i lang="en">as soon as</i>.<br>« Je t’appellerai dès que j’arriverai à l’hôtel. »', lab:'Your sentence',
  txt:[...X(['I will call you','I will phone you','I will ring you','I will give you a call'],' as soon as I ',['arrive at','get to','reach'],' the hotel.'),...X('As soon as I ',['arrive at','get to','reach'],' the hotel, ',['I will call you.','I will phone you.','I will ring you.','I will give you a call.'])],
  why:'<i lang="en">I’ll call you as soon as I arrive at the hotel.</i> Le futur est dans la proposition principale (<i lang="en">I’ll call</i>) ; après <i lang="en">as soon as</i>, on met le présent (<i lang="en">I arrive</i>), alors que le français dit « j’arriverai ».'},

 {kind:'Grammaire', h:'Le futur continu : will be + -ing',
  p:`<p>Maya dit : <i lang="en">This time next month, I’ll be packing boxes.</i> Elle ne parle pas d’une action qui commencera ou finira dans un mois, mais d’une action <b>en cours</b> à ce moment-là. Le français dit « je serai en train de faire mes cartons ».</p>
<div class="def"><p><b>will be + verbe en -ing</b>. Négation : <b>won’t be + -ing</b>. Question : <b>Will you be + -ing…?</b></p></div>
<div class="idea"><p>Trois emplois :</p><ul><li>une action <b>en cours à un moment précis du futur</b> : <i lang="en">At nine tomorrow, I’ll be driving to work</i> (j’aurai commencé avant neuf heures et je continuerai après) ;</li><li>une action qui aura lieu <b>de toute façon</b>, dans le cours normal des choses : <i lang="en">I’ll be seeing Tom at work anyway, so I’ll give him your message</i> ;</li><li>une <b>question polie</b> sur les projets de quelqu’un : <i lang="en">Will you be using the car tonight?</i> est plus délicat que <i lang="en">Will you use the car tonight?</i>, qui ressemble à une demande de décision.</li></ul></div>
<div class="ex"><p><i lang="en">Don’t call at eight: we’ll be having dinner.</i><br><i lang="en">This time next week, she’ll be lying on a beach in Crete.</i><br><i lang="en">Will you be coming to the party on Saturday?</i></p></div>
<div class="warn"><p>N’oublie ni <b>be</b> ni <b>-ing</b> : « I will be work » et « I will working » sont faux. Et pas de forme continue avec les verbes d’état (<i lang="en">know, want, like, belong, believe</i>) : <i lang="en">This time next year, I’ll know the city well</i>, pas « I’ll be knowing ».</p></div>`,
  audio:'Don’t call at eight: we’ll be having dinner. This time next week, she’ll be lying on a beach in Crete. Will you be coming to the party on Saturday?'},

 {kind:'Pratique', h:'Practice: this time tomorrow',
  p:'Translate into English with the future continuous.<br>« Demain à cette heure-ci, je serai en train de passer mon permis de conduire. »', lab:'Your sentence',
  txt:[...X(['This time tomorrow ','At this time tomorrow '],'I will be ',['taking','doing','sitting'],' my driving test.'),...X('I will be ',['taking','doing','sitting'],' my driving test ',['this time tomorrow.','at this time tomorrow.'])],
  why:'<i lang="en">This time tomorrow, I’ll be taking my driving test.</i> L’action sera en cours à ce moment-là : <i lang="en">will be + -ing</i>. « Passer un examen » se dit <i lang="en">take</i> (ou <i lang="en">do, sit</i> en britannique), jamais <i lang="en">pass</i>, qui veut dire « réussir ».'},

 {kind:'Pratique', h:'Practice: a polite question',
  p:'You would like to borrow your flatmate’s bike tonight. First, you ask politely if he needs it, with the future continuous of <i lang="en">use</i>.<br><b>Question:</b> what do you say?', lab:'Your question',
  txt:X('Will you be using ',['your bike','the bike','it','your bicycle'],[' tonight?',' this evening?']),
  why:'<i lang="en">Will you be using your bike tonight?</i> On demande ce qui est prévu, sans pousser l’autre à décider : c’est plus poli que <i lang="en">Will you use…?</i> Ensuite seulement : <i lang="en">Could I borrow it?</i>'},

 {kind:'Grammaire', h:'Plus ou moins probable',
  p:`<p>Josh ne dit pas seulement qu’il fera froid à Édimbourg : il dit <i lang="en">it’s bound to be colder</i>, c’est-à-dire qu’il en est presque sûr. Et Maya ajoute que les loyers <i lang="en">are likely to be lower</i>. Pour parler de l’avenir avec nuance, il faut savoir dire <b>à quel point</b> on est sûr.</p>
<div class="def"><ul><li><b>Certain</b> : <i lang="en">will definitely</i>, <i lang="en">be bound to + base</i> (<i lang="en">It’s bound to rain.</i>)</li><li><b>Probable</b> : <i lang="en">will probably</i>, <i lang="en">be likely to + base</i>, <i lang="en">There’s a good chance (that)…</i></li><li><b>Possible</b> : <i lang="en">may, might, could + base</i> (<i lang="en">I might have a spare room.</i>)</li><li><b>Peu probable</b> : <i lang="en">probably won’t</i>, <i lang="en">be unlikely to + base</i>, <i lang="en">I doubt (that)…</i></li><li><b>Exclu</b> : <i lang="en">definitely won’t</i></li></ul></div>
<div class="idea"><p>La place des adverbes : <b>après will</b>, mais <b>avant won’t</b>. <i lang="en">She’ll probably come. She probably won’t come.</i> Et <i lang="en">likely</i> est un adjectif : on dit <i lang="en">be likely to</i> ou <i lang="en">it’s likely that…</i> (en américain, on entend aussi <i lang="en">It will likely rain</i>).</p></div>
<div class="ex"><p><i lang="en">The match is likely to be cancelled.</i> = Le match risque d’être annulé.<br><i lang="en">He’s unlikely to win.</i> = Il a peu de chances de gagner.<br><i lang="en">I doubt they’ll come.</i> = Je doute qu’ils viennent.</p></div>
<div class="warn"><p>« Il risque de pleuvoir » ne se traduit pas avec <i lang="en">risk</i> : <i lang="en">It’s likely to rain</i> (ou <i lang="en">It might rain</i>). « He won’t probably come » est faux : <i lang="en">He probably won’t come</i>. Enfin, <i lang="en">I doubt</i> contient déjà le doute : <i lang="en">I doubt he’ll call</i> = je doute qu’il appelle (pas de <i lang="en">not</i>).</p></div>`,
  audio:'She’ll probably come. She probably won’t come. The match is likely to be cancelled. He’s unlikely to win. I doubt they’ll come.'},

 {kind:'Pratique', h:'Practice: where does probably go?',
  p:'Put the words in the correct order.<br><b>Question:</b> what is the sentence?',
  ordre:['They','probably','won’t','finish','the','work','before','Friday.'],
  why:'<i lang="en">They probably won’t finish the work before Friday.</i> Avec la négation, <i lang="en">probably</i> se place <b>avant</b> <i lang="en">won’t</i> ; à l’affirmative, après <i lang="en">will</i> : <i lang="en">They’ll probably finish</i>.'},

 {kind:'Pratique', h:'Practice: likely',
  p:'Rewrite the sentence with <i lang="en">likely</i>. Keep the same meaning.<br><i lang="en">Prices will probably go up next year.</i>', lab:'Your sentence',
  txt:V(['Prices are likely to go up next year.','Next year prices are likely to go up.','Prices are likely to rise next year.','It is likely that prices will go up next year.','It is likely that prices will rise next year.']),
  why:'<i lang="en">Prices are likely to go up next year.</i> Structure : sujet + <i lang="en">be likely to</i> + base verbale. On peut aussi dire <i lang="en">It’s likely that prices will go up next year.</i>'},

 {kind:'Prononciation', h:'’ll, won’t et want',
  p:`<p>À l’oral, <i lang="en">will</i> est presque toujours contracté. Si tu ne l’entends pas, tu crois que la phrase est au présent.</p>
<div class="def"><ul><li><b>I’ll</b> se dit comme <i lang="en">aisle</i> (« aïl »), <b>you’ll</b> « youl », <b>we’ll</b> « wil », <b>it’ll</b> « itel » (deux syllabes), <b>that’ll</b> « thatel ».</li><li><b>won’t</b> : la voyelle de <i lang="en">go</i>, longue et qui glisse (« wo-ount »). <b>want</b> : un « o » court et ouvert, comme dans <i lang="en">hot</i>.</li></ul></div>
<div class="warn"><p>Les francophones prononcent souvent <i lang="en">won’t</i> et <i lang="en">want</i> de la même façon : <i lang="en">I won’t go</i> (je n’irai pas) ressemble alors à <i lang="en">I want to go</i>, le contraire&nbsp;! Allonge bien le « o » de <i lang="en">won’t</i>. Et dans <i lang="en">I’ll</i>, ne dis pas « il » : c’est « aïl ».</p></div>
<div class="blk" data-t="À l’oral familier"><p><i lang="en">going to</i> devient souvent <b>gonna</b> : <i lang="en">I’m gonna call her</i>. Il faut le comprendre, mais ne l’écris pas dans un message soigné.</p></div>`,
  audio:'I’ll call you. You’ll love it. It’ll be fine. I won’t go. I want to go. I won’t. I want.'},

 {kind:'Oral', h:'Repeat: a promise',
  p:'Listen, then say the sentence aloud. Contract <i lang="en">will</i> (<i lang="en">I’ll</i> sounds like « aïl ») and make the difference between <i lang="en">won’t</i> (long « o ») and <i lang="en">want</i>. Stress the important words: <i lang="en">I <b>won’t</b> for<b>get</b>, I <b>prom</b>ise.</i>',
  dire:'I won’t forget, I promise. I’ll call you as soon as I land.',
  note:'Si <i lang="en">won’t</i> reste en rouge, la reconnaissance vocale a sans doute entendu <i lang="en">want</i> : allonge la voyelle et recommence.'},

 {kind:'Lecture', h:'Work in 2040',
  p:`<p>Read this magazine article, then answer the question. You can also listen to it.</p>
<div class="blk" data-t="Work in 2040: what experts expect"><p lang="en">Ask ten experts what work will look like in 2040 and you’ll get ten different answers. Still, a few predictions come up again and again. First, most office workers are likely to spend only two or three days a week in a company building. Offices won’t disappear, but they’ll be smaller and used mainly for meetings and training. Second, many of us will be working with AI assistants every day, in the same way we use email today. That doesn’t mean robots will take every job: jobs that need care, creativity or physical skill are unlikely to vanish. Third, people will probably change careers several times. A twenty-year-old today is bound to retrain at least once, perhaps at forty or fifty. Some experts are less optimistic. They doubt that companies will pay for all this training, and they warn that the gap between well-paid and badly paid workers could grow. One thing is certain: by 2040, many people reading this article will be doing jobs that don’t exist yet.</p></div>
<p><b>Question:</b> according to the article, what will happen to offices?</p>`,
  audio:'Ask ten experts what work will look like in 2040 and you’ll get ten different answers. Still, a few predictions come up again and again. First, most office workers are likely to spend only two or three days a week in a company building. Offices won’t disappear, but they’ll be smaller and used mainly for meetings and training. Second, many of us will be working with AI assistants every day, in the same way we use email today. That doesn’t mean robots will take every job: jobs that need care, creativity or physical skill are unlikely to vanish. Third, people will probably change careers several times. A twenty-year-old today is bound to retrain at least once, perhaps at forty or fifty. Some experts are less optimistic. They doubt that companies will pay for all this training, and they warn that the gap between well-paid and badly paid workers could grow. One thing is certain: by 2040, many people reading this article will be doing jobs that don’t exist yet.',
  opts:['They will disappear completely.','They will be bigger, because more people will work there.','They will be smaller and used mainly for meetings and training.','They will be replaced by AI assistants.'], ans:2,
  why:'<i lang="en">Offices won’t disappear, but they’ll be smaller and used mainly for meetings and training.</i> Remarque aussi les degrés de probabilité du texte : <i lang="en">are likely to, are unlikely to, will probably, is bound to, could</i>, et un futur continu : <i lang="en">will be working</i>.'},

 {kind:'Dictée', h:'Dictation: moving house',
  p:'Listen and write the sentence exactly. You can listen as many times as you like, and use « Plus lentement ».',
  dictee:'We’re moving to Leeds in June, so we’ll be looking for a new school.',
  why:'Deux futurs : le présent continu pour un projet organisé (<i lang="en">We’re moving</i>) et le futur continu pour une action qui sera en cours (<i lang="en">we’ll be looking</i>). Attention à l’orthographe de <i lang="en">Leeds</i> et de <i lang="en">school</i>.'},

 {kind:'Oral', h:'Talk about your next twelve months',
  p:`<p>Speak for 45 seconds to one minute about your next twelve months. Say what you are going to do (intentions), one or two things that are already arranged (with a date), what you will be doing this time next year, and how likely some things are. Tap « Parler », then « J’ai fini ».</p>`,
  oral:{modele:'Over the next twelve months, I’m going to change a few things. In September, I’m starting a new course at university, so I’m going to move closer to the campus. I’m visiting a flat next Saturday with my brother. I’ll probably need a part-time job, because rents are likely to be high. This time next year, I’ll be living in a new city and I’ll be studying full-time. It’s bound to be hard at first, but I’m sure I’ll enjoy it.',
   criteres:['I used going to for an intention','I used the present continuous for an arrangement with a date','I used the future continuous (I’ll be + -ing)','I said how likely something is (probably, likely, bound to…)','I spoke for at least 45 seconds']}},

 {kind:'Écriture', h:'Write: an email about your plans',
  p:'Your English-speaking friend Sam asks: <i lang="en">What are your plans for next year?</i> Write a reply (about 120 words). Talk about one intention, one arrangement with a date, what you will be doing this time next year, and how likely some things are. End with a question to Sam.',
  ecrire:{min:100, modele:'Hi Sam, Thanks for your message! Big news here too: I’m starting a new job in Lyon in September, so I’m going to look for a flat there this summer. I’m visiting a few places on 12 July with my sister. Rents are likely to be high, but I’m bound to find something in the end. In August, I’ll be working on my French every evening, because I’m a bit nervous about meetings in French! I probably won’t have much free time, but I’ll definitely come to your party on 3 August, I promise. This time next year, I’ll be living in a new city, which is exciting and a little scary. What about you? Are you going to stay in Bristol? Speak soon, Léa',
   criteres:[{t:'I used going to for an intention', re:'\\bgoing to \\w+'},{t:'I used the present continuous for an arrangement', re:'\\b(am|is|are|i[’\']m|we[’\']re|they[’\']re|he[’\']s|she[’\']s)\\s+(?!going\\b)\\w+ing\\b'},{t:'I used the future continuous (will be + -ing)', re:'(\\bwill|[’\']ll)\\s+be\\s+\\w+ing\\b'},{t:'I said how likely something is', re:'\\b(likely|unlikely|bound to|probably|definitely|a good chance|i doubt)\\b'},{t:'I used will or won’t for a promise or a decision', re:'\\b(will|won[’\']t)\\b|[’\']ll\\b'},{t:'I asked Sam a question', re:'\\?'}]}},

 {kind:'Récapitulatif', h:'Ce qu’il faut retenir',
  p:`<div class="keep"><ul><li><b>going to</b> : intention décidée avant, prédiction sur un indice visible (<i lang="en">I’m going to move. Look, it’s going to rain.</i>).</li><li><b>Présent continu</b> : arrangement fixé (<i lang="en">I’m flying to Berlin on Friday.</i>). <b>Présent simple</b> : horaire officiel (<i lang="en">The train leaves at 7.40.</i>).</li><li><b>will</b> : décision prise sur le moment, offre, promesse, prédiction d’opinion (<i lang="en">I’ll help you. You’ll love it.</i>).</li><li>Après <i lang="en">when, as soon as, before, after, until, if</i> : <b>présent</b> (<i lang="en">I’ll call you when I arrive</i>), contrairement au français.</li><li><b>Futur continu</b> <i lang="en">will be + -ing</i> : action en cours à un moment du futur, ou question polie (<i lang="en">This time tomorrow I’ll be flying. Will you be using the car?</i>). Jamais avec les verbes d’état.</li><li>Probabilité : <i lang="en">definitely, bound to</i> → <i lang="en">probably, likely to, a good chance</i> → <i lang="en">may, might, could</i> → <i lang="en">unlikely to, I doubt</i> → <i lang="en">definitely won’t</i>. <i lang="en">He’ll probably come / He probably won’t come.</i> « Il risque de » = <i lang="en">be likely to</i>.</li><li>Prononciation : <i lang="en">I’ll</i> « aïl » ; <i lang="en">won’t</i> (o long) ≠ <i lang="en">want</i> (o court).</li></ul></div>`},

 {kind:'Mission', h:'A weekend in the Lake District',
  p:'You are going on a weekend trip to the Lake District with your friend Dan. He has left you a voice message. Listen, then answer the questions one by one. You can listen again at any time.',
  audio:'Hi, it’s Dan. Just a quick message about Saturday. The train leaves at seven forty, so let’s meet at the station at twenty past seven, under the departures board. I’m picking up the tickets tomorrow, so you don’t need to do anything. Oh, and the forecast says it’s likely to rain on Saturday afternoon, so bring a waterproof jacket. I’ll be waiting with two coffees! Call me back if there’s a problem. Bye!', cache:true,
  parts:[
   {q:'a) What time does the train leave? Write it in figures.', lab:'Time', txt:['7.40','7:40','07.40','07:40','7.40 am','7.40 a.m.','7:40 am','7:40 a.m.'], hint:'Dan says « seven forty ». Don’t confuse it with the meeting time.', why:'<i lang="en">The train leaves at seven forty</i> = 7 h 40 (présent simple : c’est un horaire). Le rendez-vous est 20 minutes avant : <i lang="en">twenty past seven</i>, 7 h 20.'},
   {q:'b) Where will Dan be waiting?', opts:['On the train','Under the departures board','At the ticket office','In a café outside the station'], ans:1, hint:'Listen to the place he gives just after the meeting time.', why:'<i lang="en">Let’s meet at the station, under the departures board</i> (le tableau des départs). Et il précise : <i lang="en">I’ll be waiting with two coffees</i>, un futur continu.'},
   {q:'c) Why should you bring a waterproof jacket?', opts:['Because it is raining now.','Because it will definitely rain all weekend.','Because it is likely to rain on Saturday afternoon.','Because the train is not heated.'], ans:2, hint:'Listen for the word « forecast » (la météo).', why:'<i lang="en">The forecast says it’s likely to rain on Saturday afternoon</i> : il risque de pleuvoir samedi après-midi. <i lang="en">likely</i> = probable, pas certain.'},
   {q:'d) Send Dan a text message. Translate: « Je serai un peu en retard, mais j’apporterai des sandwichs. »', lab:'Your message', txt:X(['I will be a bit late','I will be a little late','I will be slightly late'],', but ',['I will bring some sandwiches.','I will bring sandwiches.']), hint:'A prediction and a decision you make now: <i lang="en">will</i>. « un peu » = <i lang="en">a bit</i>.', why:'<i lang="en">I’ll be a bit late, but I’ll bring some sandwiches.</i> Deux <i lang="en">will</i> : une prédiction (je serai en retard) et une décision prise en écrivant (j’apporterai).'}],
  sol:'<p lang="en">Hi, it’s Dan. Just a quick message about Saturday. The train leaves at seven forty, so let’s meet at the station at twenty past seven, under the departures board. I’m picking up the tickets tomorrow… The forecast says it’s likely to rain on Saturday afternoon, so bring a waterproof jacket. I’ll be waiting with two coffees!</p><p>Le train part à 7 h 40 (horaire : présent simple), Dan a organisé l’achat des billets (<i lang="en">I’m picking up</i> : présent continu), il risque de pleuvoir (<i lang="en">likely to</i>) et il t’attendra sous le tableau des départs (<i lang="en">I’ll be waiting</i> : futur continu). Ta réponse : <i lang="en">I’ll be a bit late, but I’ll bring some sandwiches.</i></p>'},

 {kind:'Mission', h:'The office move',
  p:`<p>You work for a small company. Your manager, Claire, has sent this email to the whole team. Read it, then answer the questions.</p>
<div class="blk" data-t="Email: Office move – next week"><p lang="en">Hi all,</p><p lang="en">As you know, we’re moving to the new building on Harbour Street. Here’s the plan. The removal company is coming on Thursday at 8 a.m., so please pack your desks by Wednesday evening. On Thursday and Friday, the IT team will be setting up the network, so the internet is likely to be slow or down for most of the day. If you can, work from home. The new office opens on Monday at 9. Parking there is limited and it’s bound to be busy in the first week, so I’d recommend coming by bus (the number 12 stops right outside). I’ll send everyone their new desk number before the weekend.</p><p lang="en">Thanks for your patience!<br>Claire</p></div>`,
  parts:[
   {q:'a) When must the team pack their desks?', opts:['On Thursday at 8 a.m.','By Wednesday evening','Before Monday at 9','By Friday evening'], ans:1, hint:'Look for the word « pack ».', why:'<i lang="en">Please pack your desks by Wednesday evening</i> : avant mercredi soir, car les déménageurs arrivent jeudi à 8 h (<i lang="en">The removal company is coming</i> : un arrangement, au présent continu).'},
   {q:'b) Why is the internet likely to be slow on Thursday? Answer with a full sentence from the email’s information, using the future continuous.', lab:'Your answer', long:true, txt:X(['Because the IT team ','The IT team '],'will be setting up the network',['.',' on Thursday and Friday.',' on Thursday.']), hint:'Who will be working on the network, and with which tense?', why:'<i lang="en">Because the IT team will be setting up the network.</i> Le futur continu décrit ce qui sera en cours pendant ces deux jours.'},
   {q:'c) You want to know if Claire will be at the new office on Monday morning. Ask her politely with the future continuous of <i lang="en">come</i>.', lab:'Your question', txt:X('Will you be coming to the ',['new office','office','new building'],[' on Monday?',' on Monday morning?']), hint:'<i lang="en">Will you be</i> + verb in <i lang="en">-ing</i>…?', why:'<i lang="en">Will you be coming to the new office on Monday?</i> Le futur continu rend la question neutre et polie : on demande ce qui est prévu, pas une décision.'},
   {q:'d) Reply to Claire. Translate: « Je viendrai en bus, car le parking sera forcément plein. » Use <i lang="en">bound to</i> and <i lang="en">busy</i>.', lab:'Your sentence', long:true, txt:X(['I will come by bus','I will take the bus','I will come on the bus'],[', because ',' because ',', as ',' as '],['the car park','parking'],' is bound to be busy.'), hint:'A decision made now: <i lang="en">will</i>. A near certainty: <i lang="en">be bound to</i>. « le parking » (britannique) = <i lang="en">the car park</i>.', why:'<i lang="en">I’ll come by bus, because the car park is bound to be busy.</i> En britannique, le lieu où l’on gare sa voiture est <i lang="en">a car park</i> (américain : <i lang="en">a parking lot</i>). <i lang="en">Parking</i> désigne l’action ou les places en général.'}],
  sol:'<p>Les déménageurs viennent jeudi à 8 h (<i lang="en">is coming</i> : arrangement), il faut donc emballer son bureau avant mercredi soir. Jeudi et vendredi, le service informatique installera le réseau (<i lang="en">will be setting up</i> : futur continu), si bien qu’internet risque d’être lent (<i lang="en">is likely to be slow</i>). Le nouveau bureau ouvre lundi à 9 h (horaire : <i lang="en">opens</i>). Le parking sera forcément plein (<i lang="en">is bound to be busy</i>), d’où le conseil de venir en bus. Questions et réponses possibles : <i lang="en">Will you be coming to the new office on Monday?</i> <i lang="en">I’ll come by bus, because the car park is bound to be busy.</i></p>'},
]},

/* ===================== 5. Opinions ===================== */
{subj:'en', sem:'b1', id:'en-b1-opinions', o:5, h:'Opinions', p:'Donner son avis, être d’accord ou non, nuancer poliment, et choisir entre la forme en -ing et l’infinitif après un verbe (enjoy doing, decide to do, stop doing / stop to do).', steps:[
 {kind:'Écoute', h:'The four-day week',
  p:`<p>By the end of this unit, you will be able to give your opinion, agree and disagree politely, add nuance, and use the right verb form after verbs like <i lang="en">enjoy, decide, suggest</i> or <i lang="en">stop</i>.</p>
<p>Priya and Tom work in the same office. They are discussing an email from their company. <b>Listen without reading</b>, then answer. The text will appear after your answer.</p>
<p><b>Question:</b> what is Priya’s position at the end of the conversation?</p>`,
  audio:[['Priya','Have you read the email about the four-day week trial?'],['Tom','I have. Personally, I think it’s a brilliant idea. Imagine having every Friday off!'],['Priya','I see what you mean, but I’m not so sure. We’d still have to do the same amount of work, just in four days.'],['Tom','That’s true, but studies show that people work better when they’re less tired.'],['Priya','Maybe. As far as I’m concerned, the problem is our clients. They expect someone to answer the phone on Fridays.'],['Tom','You’ve got a point there. But we could take turns: half the team could have Monday off, the other half Friday.'],['Priya','Hmm, that might work. I just hope they don’t decide to make it compulsory for everyone.'],['Tom','To be honest, I doubt they will. They’ve suggested trying it for six months first.'],['Priya','Well, I don’t mind giving it a go. If it doesn’t work, we can always stop doing it.'],['Tom','Exactly. I couldn’t agree more.']], cache:true,
  opts:['She refuses to try the four-day week.','She is willing to try it, even if she still has doubts.','She thought it was a brilliant idea from the start.','She wants it to be compulsory for everyone.'], ans:1,
  why:'Au début, Priya doute (<i lang="en">I’m not so sure</i>), puis elle accepte d’essayer : <i lang="en">I don’t mind giving it a go. If it doesn’t work, we can always stop doing it.</i> Elle ne veut surtout pas que ce soit obligatoire pour tous.'},

 {kind:'Vocabulaire', h:'Giving your opinion',
  p:`<p>Here are phrases to introduce your opinion. Tap a line to hear it, then repeat it. Vary them: using only <i lang="en">I think</i> makes your English sound flat.</p>`,
  mots:[['In my opinion,…','À mon avis,…','In my opinion, it’s too expensive.'],['Personally, I think…','Personnellement, je pense que…','Personally, I think it’s a brilliant idea.'],['As far as I’m concerned,…','En ce qui me concerne,…','As far as I’m concerned, the price is the problem.'],['If you ask me,…','Si tu veux mon avis,…','If you ask me, it won’t work.'],['It seems to me that…','Il me semble que…','It seems to me that nobody is happy.'],['I’m convinced (that)…','Je suis convaincu que…','I’m convinced it’s the right decision.'],['To be honest,…','Pour être honnête,…','To be honest, I don’t like it.'],['I have mixed feelings about…','J’ai des sentiments partagés sur…','I have mixed feelings about working from home.'],['to change your mind','changer d’avis','I’ve changed my mind.'],['What do you think of…?','Que penses-tu de… ?','What do you think of the new plan?']],
  note:'<b>Attention :</b> ne dis pas « according to me » pour ton propre avis. <i lang="en">According to</i> sert à citer une autre source : <i lang="en">according to the report, according to Tom</i>. Pour toi : <i lang="en">in my opinion</i>.'},

 {kind:'Vocabulaire', h:'Agreeing, disagreeing and nuancing',
  p:`<p>Now, phrases to react to someone else’s opinion. Notice how many of them say « yes, but… »: in English, a direct « no » can sound rude.</p>`,
  mots:[['I agree (with you)','Je suis d’accord (avec toi)','I agree with you about the price.'],['I couldn’t agree more','Je suis entièrement d’accord','– It’s far too long. – I couldn’t agree more.'],['That’s a good point','C’est juste, bien vu','That’s a good point, I hadn’t thought of that.'],['You’ve got a point (there)','Tu n’as pas tort','You’ve got a point, but it’s risky.'],['I see what you mean, but…','Je vois ce que tu veux dire, mais…','I see what you mean, but it’s not that simple.'],['I’m not so sure (about that)','Je n’en suis pas si sûr','I’m not so sure about that.'],['I totally disagree','Je ne suis pas du tout d’accord','I totally disagree with the decision.'],['It depends (on…)','Ça dépend (de…)','It depends on the weather.'],['On the one hand… on the other hand…','D’un côté… de l’autre…','On the one hand it’s cheap; on the other hand it’s slow.'],['to some extent','dans une certaine mesure','I agree to some extent.'],['to give it a go','essayer, tenter le coup','I don’t mind giving it a go.']],
  note:'On dit <i lang="en">I agree</i>, jamais « I am agree » : <i lang="en">agree</i> est un verbe. Négation : <i lang="en">I don’t agree</i> ou <i lang="en">I disagree</i>. Et <i lang="en">depend</i> se construit avec <b>on</b> : <i lang="en">it depends on you</i>, pas « depends of ».'},

 {kind:'Pratique', h:'Recall: agreeing',
  p:'Translate into English.<br>« Je suis tout à fait d’accord avec toi. »', lab:'Your sentence',
  txt:[...X(['I completely agree','I totally agree','I fully agree','I absolutely agree','I entirely agree','I agree completely','I agree entirely','I agree totally'],' with you.'),...X(['I agree with you completely.','I agree with you entirely.','I agree with you totally.','I couldn’t agree more.','I couldn’t agree with you more.'])],
  why:'<i lang="en">I completely agree with you</i>, ou plus expressif : <i lang="en">I couldn’t agree more</i>. Jamais « I am agree » : <i lang="en">agree</i> est un verbe, pas un adjectif.'},

 {kind:'Grammaire', h:'Donner son avis sans calque du français',
  p:`<p>Tom dit <i lang="en">Personally, I think it’s a brilliant idea</i> et Priya répond <i lang="en">I see what you mean, but I’m not so sure</i>. Donner son avis en anglais, ce n’est pas seulement traduire « je pense que » : il faut choisir une formule, réagir à l’autre, nuancer, et éviter quelques calques très fréquents.</p>
<div class="def"><p>Les trois gestes d’un avis bien construit :</p><ul><li><b>annoncer</b> son point de vue : <i lang="en">In my opinion… / Personally, I think… / As far as I’m concerned…</i></li><li><b>réagir</b> à l’autre : <i lang="en">I agree / I don’t agree, That’s a good point, I see what you mean, but…</i></li><li><b>nuancer</b> : <i lang="en">to some extent, it depends on…, on the one hand… on the other hand…, I’m not so sure</i>.</li></ul></div>
<div class="idea"><p>En anglais, et surtout au Royaume-Uni, un désaccord direct (<i lang="en">You’re wrong</i>) paraît brutal. On commence presque toujours par reconnaître l’avis de l’autre, puis on ajoute <i lang="en">but</i> : <i lang="en">You’ve got a point, but…</i> C’est poli, et ça rend ton propre argument plus convaincant.</p></div>
<div class="ex"><p><i lang="en">I don’t think it’s a good idea.</i> = Je pense que ce n’est pas une bonne idée.<br><i lang="en">– Will it work? – I don’t think so.</i> = Je pense que non.<br><i lang="en">– Is it expensive? – I think so.</i> = Je pense que oui.</p></div>
<div class="warn"><p>Les calques à éviter : <b>« I am agree »</b> → <i lang="en">I agree</i>. <b>« According to me »</b> → <i lang="en">In my opinion</i>. <b>« I think that no »</b> → <i lang="en">I don’t think so</i>. <b>« I think it isn’t a good idea »</b> n’est pas faux, mais l’anglais préfère nettement mettre la négation sur <i lang="en">think</i> : <i lang="en">I don’t think it’s a good idea</i>. Enfin, <i lang="en">actually</i> veut dire « en fait », pas « actuellement » (<i lang="en">currently, at the moment</i>).</p></div>`,
  audio:'Personally, I think it’s a brilliant idea. I see what you mean, but I’m not so sure. I don’t think it’s a good idea. I don’t think so.'},

 {kind:'Pratique', h:'Practice: the negative on think',
  p:'Rewrite the sentence in a more natural way. Put the negative on <i lang="en">think</i>.<br><i lang="en">I think it isn’t a good idea to drive.</i>', lab:'Your sentence',
  txt:V(['I do not think it is a good idea to drive.','I do not think that it is a good idea to drive.','I do not think driving is a good idea.']),
  why:'<i lang="en">I don’t think it’s a good idea to drive.</i> En anglais, la négation se place naturellement sur le verbe d’opinion (<i lang="en">think, believe, expect</i>), même si le français dit « je pense que ce n’est pas… ».'},

 {kind:'Pratique', h:'Practice: disagreeing politely',
  p:'Your colleague says: <i lang="en">We should cancel the project.</i> You disagree politely. Translate into English.<br>« Je vois ce que tu veux dire, mais je n’en suis pas si sûr. »', lab:'Your answer',
  txt:X(['I see what you mean','I understand what you mean','I know what you mean'],', but ',['I am not so sure.','I am not so sure about that.','I am not sure.','I am not sure about that.']),
  why:'<i lang="en">I see what you mean, but I’m not so sure.</i> On reconnaît d’abord le point de vue de l’autre, puis on exprime son doute avec <i lang="en">but</i> : c’est la forme polie du désaccord.'},

 {kind:'Grammaire', h:'Verbe + -ing ou verbe + to ?',
  p:`<p>Dans le dialogue, on entend <i lang="en">They’ve suggested <b>trying</b> it</i> et <i lang="en">I don’t mind <b>giving</b> it a go</i>, mais <i lang="en">I hope they don’t decide <b>to make</b> it compulsory</i>. Quand un verbe en suit un autre, l’anglais impose soit la forme en <b>-ing</b> (le gérondif), soit <b>to + base verbale</b> (l’infinitif). Le français met presque toujours l’infinitif, d’où beaucoup d’erreurs.</p>
<div class="def"><ul><li><b>verbe + -ing</b> : <i lang="en">enjoy, avoid, mind, finish, suggest, consider, keep, miss, practise, risk, imagine, admit, deny, can’t stand, give up, carry on</i>. <i lang="en">I enjoy cooking. She keeps calling me.</i></li><li><b>verbe + to + base</b> : <i lang="en">want, would like, decide, hope, plan, agree, refuse, promise, manage, afford, offer, expect, seem, learn, choose, need</i>. <i lang="en">We decided to stay. He refused to pay.</i></li><li><b>après une préposition</b>, toujours <b>-ing</b> : <i lang="en">interested in learning, good at drawing, thank you for coming, instead of driving, before leaving</i>.</li></ul></div>
<div class="idea"><p>Une tendance aide à retenir : les verbes suivis de <b>to</b> regardent souvent <b>vers l’avant</b>, vers un projet (<i lang="en">want, hope, plan, decide, promise to…</i>) ; les verbes suivis de <b>-ing</b> parlent plutôt d’une activité vécue ou envisagée en elle-même (<i lang="en">enjoy, mind, avoid, finish doing</i>). Ce n’est pas une règle absolue : apprends chaque verbe avec sa construction, comme un bloc.</p></div>
<div class="warn"><p>Les pièges des francophones : <b>« I enjoy to read »</b> → <i lang="en">I enjoy reading</i>. <b>« She suggested to go »</b> (calque de « suggérer de ») → <i lang="en">She suggested going</i>. <b>« Thank you for to help me »</b> → <i lang="en">Thank you for helping me</i>. <b>« I look forward to see you »</b> → <i lang="en">I look forward to seeing you</i>, car ici <i lang="en">to</i> est une préposition. Et jamais « avoid to ».</p></div>`,
  audio:'I enjoy cooking. She keeps calling me. We decided to stay. He refused to pay. Thank you for coming.'},

 {kind:'Méthode', h:'Choisir entre -ing et to',
  p:`<p><b>Quand :</b> chaque fois qu’un verbe est suivi d’un autre verbe. <b>Pourquoi ça marche :</b> la construction dépend du mot qui précède (un verbe ou une préposition), pas de la phrase française ; il suffit donc de regarder ce mot. <b>Comment :</b></p>
<ol><li>Le mot qui précède est-il une <b>préposition</b> (<i lang="en">in, at, of, for, about, without, before, after, instead of</i>, et le <i lang="en">to</i> de <i lang="en">look forward to</i>)&nbsp;? → <b>-ing</b>.</li><li>Sinon, le premier verbe est-il de la famille <i lang="en">enjoy, avoid, mind, suggest, finish, keep, consider</i>…&nbsp;? → <b>-ing</b>.</li><li>Est-il de la famille <i lang="en">want, decide, hope, plan, agree, refuse, promise, afford</i>…&nbsp;? → <b>to + base</b>.</li><li>Est-ce <i lang="en">stop, remember, forget, try</i>&nbsp;? → les deux existent, avec des sens différents : regarde le sens (étape plus loin).</li></ol>`,
  demo:{enonce:'Complète : (1) <i lang="en">She’s thinking of ___ (change) jobs.</i> (2) <i lang="en">Would you consider ___ (work) part-time?</i> (3) <i lang="en">We can’t afford ___ (buy) a new car.</i>',
   etapes:[{f:'(1) <i lang="en">She’s thinking of changing jobs.</i>',w:'Le mot qui précède est la préposition <i lang="en">of</i> : après une préposition, toujours <b>-ing</b>.'},
    {f:'(2) <i lang="en">Would you consider working part-time?</i>',w:'<i lang="en">consider</i> appartient à la famille des verbes suivis de <b>-ing</b>.'},
    {f:'(3) <i lang="en">We can’t afford to buy a new car.</i>',w:'<i lang="en">afford</i> (avoir les moyens de) est suivi de <b>to + base</b>.'}],
   conclusion:'<i lang="en">thinking of changing</i> (préposition), <i lang="en">consider working</i> (verbe en -ing), <i lang="en">afford to buy</i> (verbe en to).'}},

 {kind:'Pratique', h:'Practice: decide',
  p:'Complete with the correct form of the verb in brackets. Write the missing words only.<br><i lang="en">It was raining, so we decided ___ (take) the train.</i>', lab:'Missing words', txt:['to take'],
  why:'<i lang="en">decide</i> est suivi de <b>to + base verbale</b> : <i lang="en">we decided to take the train</i>. Un projet, tourné vers l’avant.'},

 {kind:'Pratique', h:'Practice: suggest',
  p:'Translate into English. Use the verb <i lang="en">suggest</i>.<br>« Elle a proposé d’aller au nouveau restaurant thaï. »', lab:'Your sentence',
  txt:[...X('She suggested ',['going to','trying'],' the new Thai restaurant.'),...X('She suggested ',['that we go','that we should go','we go'],' to the new Thai restaurant.')],
  why:'<i lang="en">She suggested going to the new Thai restaurant.</i> Après <i lang="en">suggest</i>, on met <b>-ing</b> (ou <i lang="en">that we go</i>), jamais « suggested to go ». Attention : <i lang="en">She offered to go</i> voudrait dire qu’elle s’est proposée pour y aller elle-même.'},

 {kind:'Pratique', h:'Practice: after a preposition',
  p:'Translate into English.<br>« Merci de m’avoir aidé avec mon CV. »', lab:'Your sentence',
  txt:X(['Thank you','Thanks','Thanks a lot','Thank you very much'],' for helping me with my ',['CV.','résumé.']),
  why:'<i lang="en">Thank you for helping me with my CV.</i> <i lang="en">for</i> est une préposition, donc <b>-ing</b>. Le passé « m’avoir aidé » n’a pas besoin d’être marqué : le contexte suffit. (CV en britannique, <i lang="en">résumé</i> en américain.)'},

 {kind:'Grammaire', h:'Stop, remember, forget, try : deux sens',
  p:`<p>À la fin du dialogue, Priya dit <i lang="en">we can always stop doing it</i> : arrêter de le faire. Mais <i lang="en">we could stop to eat</i> voudrait dire « nous arrêter pour manger ». Avec quelques verbes, <b>-ing</b> et <b>to</b> sont tous deux possibles, mais le sens change complètement.</p>
<div class="def"><ul><li><b>stop doing</b> = arrêter de faire : <i lang="en">I stopped smoking.</i> / <b>stop to do</b> = s’arrêter pour faire : <i lang="en">I stopped to buy some water.</i></li><li><b>remember doing</b> = se souvenir d’avoir fait (passé) : <i lang="en">I remember meeting her.</i> / <b>remember to do</b> = penser à faire (à venir) : <i lang="en">Remember to lock the door.</i></li><li><b>forget doing</b> = oublier un souvenir, surtout dans <i lang="en">I’ll never forget…</i> : <i lang="en">I’ll never forget seeing the sea for the first time.</i> / <b>forget to do</b> = oublier de faire : <i lang="en">I forgot to call him.</i></li><li><b>try doing</b> = essayer une solution, pour voir : <i lang="en">Try restarting the computer.</i> / <b>try to do</b> = s’efforcer de faire une chose difficile : <i lang="en">I tried to open the window, but it was stuck.</i></li></ul></div>
<div class="idea"><p>Une image pour s’en souvenir : <b>to</b> regarde vers une action qui vient <b>après</b> (je m’arrête, puis j’achète ; je pense à la porte, puis je la ferme) ; <b>-ing</b> désigne une action <b>déjà là</b> ou déjà vécue (j’arrête une habitude en cours ; je garde un souvenir).</p></div>
<div class="warn"><p>« J’ai arrêté de fumer » = <i lang="en">I stopped smoking</i>. <i lang="en">I stopped to smoke</i> veut dire « je me suis arrêté pour fumer » : presque le contraire&nbsp;! En revanche, <i lang="en">like, love, hate, prefer, start, begin, continue</i> acceptent les deux formes sans vrai changement de sens : <i lang="en">It started raining / It started to rain</i>.</p></div>`,
  audio:'I stopped smoking. I stopped to buy some water. Remember to lock the door. I’ll never forget seeing the sea for the first time.'},

 {kind:'Pratique', h:'Practice: stop',
  p:'Translate into English.<br>« Sur le chemin du retour, il s’est arrêté pour acheter du pain. »', lab:'Your sentence',
  txt:[...X(['On the way home, ','On his way home, ',''],'he stopped to ',['buy','get'],[' some bread.',' bread.']),...X('He stopped to ',['buy','get'],[' some bread',' bread'],' on ',['the','his'],' way home.')],
  why:'<i lang="en">On his way home, he stopped to buy some bread.</i> « s’arrêter <b>pour</b> faire » = <i lang="en">stop to do</i>. <i lang="en">He stopped buying bread</i> voudrait dire qu’il n’achète plus de pain.'},

 {kind:'Pratique', h:'Practice: never forget',
  p:'Put the words in the correct order.<br><b>Question:</b> how do you say « Je n’oublierai jamais le moment où j’ai vu les aurores boréales »?',
  ordre:['I’ll','never','forget','seeing','the','Northern','Lights.'],
  why:'<i lang="en">I’ll never forget seeing the Northern Lights.</i> <i lang="en">forget + -ing</i> parle d’un souvenir vécu. <i lang="en">Don’t forget to see…</i> voudrait dire « n’oublie pas d’aller voir ».'},

 {kind:'Prononciation', h:'Intonation : convaincu ou réservé ?',
  p:`<p>En anglais, la mélodie de la voix dit autant que les mots. Un même <i lang="en">That’s a good idea</i> peut être sincère ou cacher un « mais ».</p>
<div class="def"><ul><li><b>Intonation descendante</b> (la voix tombe sur le dernier mot important) : on est sûr, on conclut. <i lang="en">I couldn’t agree <b>more</b>.</i> ↘</li><li><b>Intonation descendante-montante</b> (la voix descend puis remonte sur le mot important) : on accepte en partie, avec une réserve. <i lang="en">It’s a good idea… in <b>theory</b>.</i> ↘↗ L’auditeur entend : « mais… ».</li></ul></div>
<div class="idea"><p>L’accent tombe sur le mot qui porte l’opinion : <i lang="en">I <b>totally</b> disagree. I see what you <b>mean</b>, but… I’m not <b>so</b> sure.</i> Dans <i lang="en">I couldn’t agree more</i>, c’est <b>more</b> qui est fort.</p></div>
<div class="warn"><p>Les francophones montent souvent la voix en fin de phrase, ce qui donne un air de question ou d’hésitation. Pour un avis ferme, fais <b>descendre</b> la voix sur le dernier mot accentué.</p></div>`,
  audio:'I couldn’t agree more. It’s a good idea, in theory. I see what you mean, but I’m not so sure.'},

 {kind:'Oral', h:'Repeat from memory',
  p:'This sentence is from the dialogue. Listen, then say it from memory. Use a fall-rise on <i lang="en">mean</i> and stress <i lang="en">so</i>: you agree a little, but you have doubts.',
  dire:{t:'I see what you mean, but I’m not so sure.', cache:true}},

 {kind:'Lecture', h:'Homework: yes or no?',
  p:`<p>Read this opinion column from a parents’ magazine, then answer the question. You can also listen to it.</p>
<div class="blk" data-t="Should we stop giving children homework?"><p lang="en">Every September, the same debate comes back: should primary schools stop giving homework? As a teacher and a parent, I have mixed feelings. On the one hand, there is little evidence that homework helps children under eleven learn more. Many parents can’t afford to stay at home in the evening to help, so homework often increases the gap between pupils. And children need time to play, to read for pleasure and simply to be bored. On the other hand, I don’t think banning it completely is the answer. Ten minutes of reading a day really does make a difference, and practising times tables at home builds good habits. In my experience, the problem isn’t homework itself but the amount of it. So here is my suggestion: let’s stop setting long worksheets and start encouraging short, regular activities that children actually enjoy doing. Parents, what do you think? I’d love to hear your views, even if you disagree with me.</p></div>
<p><b>Question:</b> what is the writer’s main opinion?</p>`,
  audio:'Every September, the same debate comes back: should primary schools stop giving homework? As a teacher and a parent, I have mixed feelings. On the one hand, there is little evidence that homework helps children under eleven learn more. Many parents can’t afford to stay at home in the evening to help, so homework often increases the gap between pupils. And children need time to play, to read for pleasure and simply to be bored. On the other hand, I don’t think banning it completely is the answer. Ten minutes of reading a day really does make a difference, and practising times tables at home builds good habits. In my experience, the problem isn’t homework itself but the amount of it. So here is my suggestion: let’s stop setting long worksheets and start encouraging short, regular activities that children actually enjoy doing. Parents, what do you think? I’d love to hear your views, even if you disagree with me.',
  opts:['Homework should be banned completely in primary schools.','Primary school children should get more homework.','Homework should be short, regular and enjoyable, not banned.','Parents should do their children’s homework with them every evening.'], ans:2,
  why:'L’auteur est nuancé (<i lang="en">I have mixed feelings, on the one hand… on the other hand</i>) : il ne veut pas supprimer les devoirs (<i lang="en">I don’t think banning it completely is the answer</i>) mais les réduire à des activités courtes et agréables. Remarque <i lang="en">stop setting, start encouraging, enjoy doing, can’t afford to stay</i>.'},

 {kind:'Dictée', h:'Dictation: working from home',
  p:'Listen and write the sentence exactly. You can listen as many times as you like.',
  dictee:'I really enjoy working from home, but I miss seeing my colleagues.',
  why:'Deux verbes suivis de <b>-ing</b> : <i lang="en">enjoy working</i>, <i lang="en">miss seeing</i>. Vérifie l’orthographe de <i lang="en">colleagues</i> (deux l, -gues).'},

 {kind:'Oral', h:'Give your opinion',
  p:`<p>Speak for 45 seconds to one minute on this question: <i lang="en">Should cars be banned from city centres?</i> Introduce your opinion with a set phrase, give two arguments, mention the other side, and finish with a conclusion. Tap « Parler », then « J’ai fini ».</p>`,
  oral:{modele:'In my opinion, cars should be banned from city centres, at least at weekends. On the one hand, the air would be cleaner and the streets much quieter, and people would enjoy walking and cycling more. On the other hand, I see the problem for older people and for shops that need deliveries. So, to some extent, it depends on public transport: if buses are cheap and frequent, I think most people will stop using their cars in town. Personally, I’d be happy to give it a go.',
   criteres:['I introduced my opinion with a set phrase (In my opinion, Personally…)','I gave at least two arguments','I mentioned the other side (On the other hand, I see the problem…)','I used a verb + -ing or a verb + to correctly','I finished with a clear conclusion']}},

 {kind:'Écriture', h:'Write: a forum comment',
  p:'A forum asks: <i lang="en">Should smartphones be banned in schools?</i> Write a comment (about 120 words). Give your opinion, at least two arguments, one argument from the other side, and a conclusion. Use at least one verb + <i lang="en">-ing</i> and one verb + <i lang="en">to</i>.',
  ecrire:{min:100, modele:'In my opinion, smartphones should be banned during lessons, but not completely. On the one hand, phones make it very hard to concentrate. Many teenagers can’t stop checking their notifications, and some pupils avoid talking to each other at break because they are on social media. Teachers also waste a lot of time asking students to put their phones away. On the other hand, phones can be useful: some pupils need to call their parents after school, and a few apps really help with homework. So, as far as I’m concerned, the best solution is to keep phones in lockers during the day and let students use them before and after school. I’m convinced that most pupils would enjoy talking to their friends more. What do you think?',
   criteres:[{t:'I introduced my opinion with a set phrase', re:'\\b(in my opinion|personally|as far as i[’\']m concerned|if you ask me|i think|i believe|i[’\']m convinced|it seems to me)\\b'},{t:'I showed the other side (but, however, on the other hand…)', re:'\\b(on the other hand|however|although|but|that said)\\b'},{t:'I used a verb or a preposition + -ing', re:'\\b(enjoy|enjoys|enjoyed|avoid|avoids|avoided|stop|stops|stopped|mind|keep|keeps|suggest|suggests|finish|miss|risk|consider|without|instead of|for|about|of|at|in)\\s+(?!(some|any|no|every)thing\\b)\\w+ing\\b'},{t:'I used a verb + to + base verb', re:'\\b(want|wants|wanted|decide|decided|hope|hopes|plan|plans|need|needs|refuse|refused|manage|managed|agree|agreed|learn|choose|afford|promise|promised|would like|seem|seems)\\s+to\\s+\\w+'},'I gave at least two arguments and a conclusion','I wrote about 120 words']}},

 {kind:'Récapitulatif', h:'Ce qu’il faut retenir',
  p:`<div class="keep"><ul><li>Annoncer son avis : <i lang="en">In my opinion, Personally I think, As far as I’m concerned, If you ask me, To be honest</i>. Jamais « according to me » pour soi.</li><li>Réagir : <i lang="en">I agree (with you), I couldn’t agree more, That’s a good point, You’ve got a point, but…, I see what you mean, but…, I’m not so sure, I totally disagree</i>. Jamais « I am agree ».</li><li>Nuancer : <i lang="en">to some extent, it depends on…, on the one hand… on the other hand…</i></li><li>Négation sur <i lang="en">think</i> : <i lang="en">I don’t think it’s a good idea. I don’t think so / I think so.</i></li><li><b>-ing</b> après <i lang="en">enjoy, avoid, mind, finish, suggest, consider, keep, miss</i> et après toute <b>préposition</b> (<i lang="en">thank you for helping, look forward to seeing</i>).</li><li><b>to + base</b> après <i lang="en">want, decide, hope, plan, agree, refuse, promise, manage, afford</i>.</li><li>Changement de sens : <i lang="en">stop doing</i> (arrêter) / <i lang="en">stop to do</i> (s’arrêter pour) ; <i lang="en">remember doing</i> (se souvenir) / <i lang="en">remember to do</i> (penser à) ; <i lang="en">forget doing / forget to do</i> ; <i lang="en">try doing</i> (essayer pour voir) / <i lang="en">try to do</i> (s’efforcer).</li><li>Intonation : descendante pour un avis ferme, descendante-montante pour une réserve.</li></ul></div>`},

 {kind:'Mission', h:'The team day',
  p:'Your team is choosing an activity for its team day in June. Listen to the meeting, then answer the questions one by one. You can listen again at any time.',
  audio:[['Sarah','OK, everyone, we need to decide what to do for the team day. The options are a cooking class, an escape room or a hike in the hills.'],['Ali','If you ask me, the cooking class is the best option. Everyone enjoys eating, and we’d actually learn something useful.'],['Ben','Hmm, I’m not so sure. To be honest, I can’t stand cooking, and I’m a vegetarian, so most of the menus aren’t great for me.'],['Sarah','Fair point. What about the hike? It’s free, and it would be nice to get some fresh air.'],['Ben','It depends on the weather. I don’t fancy walking for five hours in the rain.'],['Ali','You’ve got a point. So, the escape room? It only takes two hours, and it’s indoors.'],['Sarah','I couldn’t agree more. It’s good for teamwork, too. Shall we book it for the twelfth?'],['Ben','Fine by me. And afterwards we could stop for a pizza on the way back.'],['Ali','Perfect. Just remember to book a vegetarian option, Sarah!']], cache:true,
  parts:[
   {q:'a) Why doesn’t Ben want the cooking class?', opts:['It is too expensive.','He can’t stand cooking, and the menus aren’t great for vegetarians.','It takes five hours.','He wants to be outside.'], ans:1, hint:'Listen to Ben’s first reply, after <i lang="en">To be honest</i>.', why:'<i lang="en">I can’t stand cooking, and I’m a vegetarian, so most of the menus aren’t great for me.</i> Remarque <i lang="en">can’t stand + -ing</i> (ne pas supporter de).'},
   {q:'b) Which activity do they choose? Write it in English.', lab:'The activity', txt:['the escape room','escape room','an escape room','they choose the escape room','they chose the escape room'], hint:'It only takes two hours and it’s indoors.', why:'<i lang="en">The escape room</i>, réservé pour le 12. Sarah est entièrement d’accord : <i lang="en">I couldn’t agree more</i>.'},
   {q:'c) Ali reminds Sarah to book a vegetarian option. Rewrite his sentence, starting with <i lang="en">Don’t forget…</i>', lab:'Your sentence', txt:[...X('Don’t forget to book a vegetarian option',['.',', Sarah.']),'Sarah, don’t forget to book a vegetarian option.'], hint:'Is it something to do in the future, or a memory?', why:'<i lang="en">Don’t forget to book a vegetarian option.</i> Une action à faire : <i lang="en">forget / remember + to</i>. <i lang="en">Remember booking</i> voudrait dire « se souvenir d’avoir réservé ».'},
   {q:'d) Ben suggests stopping for a pizza on the way back. What does <i lang="en">we could stop for a pizza</i> mean?', opts:['Nous pourrions arrêter de manger des pizzas.','Nous pourrions nous arrêter pour manger une pizza.','Nous pourrions commander une pizza au bureau.','Nous pourrions éviter la pizzeria.'], ans:1, hint:'<i lang="en">stop for + nom</i> works like <i lang="en">stop to + verb</i>.', why:'<i lang="en">stop for a pizza</i> = s’arrêter pour une pizza, comme <i lang="en">stop to eat a pizza</i>. « Arrêter de manger des pizzas » serait <i lang="en">stop eating pizza</i>.'},
   {q:'e) Write the expression Sarah uses to say « Je suis entièrement d’accord ».', lab:'The expression', txt:['I couldn’t agree more.','I could not agree more.'], hint:'It’s a negative sentence with <i lang="en">more</i>.', why:'<i lang="en">I couldn’t agree more</i> : littéralement « je ne pourrais pas être plus d’accord ». La voix descend sur <b>more</b>.'}],
  sol:'<p>Ali propose le cours de cuisine (<i lang="en">If you ask me…</i>). Ben n’est pas convaincu (<i lang="en">I’m not so sure… I can’t stand cooking</i>) et ne veut pas marcher cinq heures sous la pluie (<i lang="en">I don’t fancy walking</i>). L’équipe choisit l’escape game, réservé pour le 12 ; Sarah est entièrement d’accord (<i lang="en">I couldn’t agree more</i>). Au retour, ils s’arrêteront pour une pizza (<i lang="en">stop for a pizza</i>), et Ali rappelle : <i lang="en">Don’t forget to book a vegetarian option.</i></p>'},

 {kind:'Mission', h:'A strong opinion online',
  p:`<p>You read this post on a language learners’ forum. Read it, then answer the questions.</p>
<div class="blk" data-t="Forum: Language apps are a waste of time"><p lang="en">I’ve been using a popular language app for two years and, honestly, I still can’t hold a conversation. I enjoy collecting points, and I never forget to do my daily lesson, but I’m convinced that it isn’t real learning. You tap on words, you avoid making mistakes, and you never have to speak to a real person. As far as I’m concerned, the only way to learn a language is to talk to people, even if it’s scary. Last month I decided to stop using the app, and I joined a conversation group instead. I’m still nervous, but I’ve learnt more in four weeks than in two years. Some people say apps are a good start. Maybe. But I think most of us use them to feel busy, not to make progress. Am I being unfair?</p></div>`,
  parts:[
   {q:'a) What is the writer’s main argument?', opts:['Apps are the best way to learn a language.','Apps make you feel busy, but you really learn by talking to people.','Conversation groups are too expensive.','He has given up learning languages.'], ans:1, hint:'Look at <i lang="en">As far as I’m concerned…</i> and the last sentences.', why:'<i lang="en">The only way to learn a language is to talk to people</i>, et <i lang="en">most of us use them to feel busy, not to make progress</i>. Il n’a pas abandonné : il a rejoint un groupe de conversation.'},
   {q:'b) Someone replies: <i lang="en">I am agree with you, apps are useless.</i> Correct the mistake and write the whole sentence.', lab:'Corrected sentence', txt:['I agree with you, apps are useless.','I agree with you; apps are useless.','I agree with you: apps are useless.'], hint:'Is <i lang="en">agree</i> an adjective or a verb?', why:'<i lang="en">I agree with you</i> : <i lang="en">agree</i> est un verbe, il ne prend pas <i lang="en">am</i>.'},
   {q:'c) Give the writer some advice. Translate: « Je te suggère de parler dix minutes par jour. »', lab:'Your sentence', txt:X(['I suggest speaking','I suggest talking','I suggest that you speak','I suggest you speak','I would suggest speaking'],[' for ten minutes',' ten minutes'],[' a day.',' every day.',' each day.',' per day.']), hint:'<i lang="en">suggest</i> + which form?', why:'<i lang="en">I suggest speaking for ten minutes a day</i> (ou <i lang="en">I suggest that you speak…</i>). Jamais « I suggest you to speak », calque de « je te suggère de ».'},
   {q:'d) Join the two sentences into one, with <i lang="en">stopped</i>: <i lang="en">I stopped. I wanted to check my phone.</i>', lab:'Your sentence', txt:['I stopped to check my phone.'], hint:'You stopped walking <b>in order to</b> do something.', why:'<i lang="en">I stopped to check my phone</i> : je me suis arrêté pour regarder mon téléphone. <i lang="en">I stopped checking my phone</i> voudrait dire que je ne le regarde plus.'},
   {q:'e) Disagree politely with the writer, in one sentence. Translate: « Tu n’as pas tort, mais les applis peuvent être un bon début. »', lab:'Your sentence', long:true, txt:V(X(['You have got a point','You have a point','That is a good point','You have got a point there'],', but ',['apps can be a good start.','apps can be a good way to start.','apps can be a good beginning.'])), hint:'Start by recognising his point: <i lang="en">You’ve got…</i>', why:'<i lang="en">You’ve got a point, but apps can be a good start.</i> On reconnaît l’argument de l’autre avant de nuancer avec <i lang="en">but</i> : désaccord poli.'}],
  sol:'<p>L’auteur aime collectionner les points (<i lang="en">enjoy collecting</i>) et n’oublie jamais sa leçon (<i lang="en">never forget to do</i>), mais il est convaincu que ce n’est pas un vrai apprentissage : on évite de faire des erreurs (<i lang="en">avoid making</i>) et on ne parle jamais. Il a décidé d’arrêter l’application (<i lang="en">decided to stop using</i>). Réponses possibles : <i lang="en">I agree with you</i> (pas « I am agree ») ; <i lang="en">I suggest speaking for ten minutes a day</i> ; <i lang="en">I stopped to check my phone</i> ; <i lang="en">You’ve got a point, but apps can be a good start.</i></p>'},
]},

/* ===================== 6. Imagine ===================== */
{subj:'en', sem:'b1', id:'en-b1-hypotheses', o:6, h:'Imagine', p:'Imaginer, rêver et conseiller : le deuxième conditionnel, If I were you, et I wish pour regretter le présent.', steps:[
 {kind:'Écoute', h:'After work',
  p:`<p>By the end of this unit, you will be able to talk about imaginary situations and their consequences, give advice with <i lang="en">If I were you</i>, and say what you wish were different in your life.</p>
<p>Sam and his friend Lucy are having a drink after work. <b>Listen without reading</b>, then answer. The text will appear after your answer.</p>
<p><b>Question:</b> what would Sam do if he had more savings?</p>`,
  audio:[['Lucy','You look exhausted, Sam. Is it work again?'],['Sam','Yeah. I spend all day answering complaints. Honestly, if I had the choice, I’d quit tomorrow.'],['Lucy','So why don’t you? You’ve been saying that for a year.'],['Sam','Because I’ve got rent to pay! If I had more savings, I’d go back to university and study architecture. That’s what I’ve always wanted to do.'],['Lucy','Could you study part-time?'],['Sam','Maybe, but I wouldn’t have time for anything else. I wish I didn’t have to work on Saturdays.'],['Lucy','Look, if I were you, I’d talk to your manager. Ask if you could work four days a week.'],['Sam','She’d never agree.'],['Lucy','You don’t know that. And if she said no, you wouldn’t be any worse off than now.'],['Sam','True. I wish I were braver, like you.'],['Lucy','I’m not brave! I just hate seeing you so unhappy.']], cache:true,
  opts:['He would move abroad.','He would ask for a pay rise.','He would go back to university and study architecture.','He would buy a flat.'], ans:2,
  why:'<i lang="en">If I had more savings, I’d go back to university and study architecture.</i> Il n’a pas ces économies : c’est une situation imaginaire, d’où le prétérit (<i lang="en">had</i>) et <i lang="en">would</i> (<i lang="en">I’d</i>).'},

 {kind:'Vocabulaire', h:'Dreams, wishes and choices',
  p:`<p>Here are phrases for dreams, regrets and advice. Tap a line to hear it, then repeat it. Pay attention to <i lang="en">’d</i>: it is the short form of <i lang="en">would</i>.</p>`,
  mots:[['What would you do if…?','Que ferais-tu si… ?','What would you do if you won a million?'],['If I were you, I’d… / If I were you, I would…','À ta place, je…','If I were you, I’d say yes.'],['I wish I could…','J’aimerais pouvoir…','I wish I could sing.'],['if only…','si seulement…','If only I had more time!'],['to be stuck (in a job)','être coincé (dans un travail)','He feels stuck in a boring job.'],['to quit (your job)','démissionner, tout lâcher','She quit her job to travel.'],['savings','des économies','I used my savings to buy a car.'],['to afford (to do)','avoir les moyens de','We can’t afford to go on holiday this year.'],['to be better off / worse off','être mieux loti / plus mal loti','We’d be better off without a car.'],['to take a gap year','prendre une année sabbatique','I’d love to take a gap year.'],['to win the lottery','gagner au loto','If I won the lottery, I’d buy an island.'],['a dream come true','un rêve devenu réalité','Living by the sea would be a dream come true.'],['to make a living','gagner sa vie','It’s hard to make a living as an artist.'],['to turn down (an offer)','refuser (une offre)','I’d never turn down a job like that.'],['to have second thoughts','avoir des doutes, hésiter','I’m having second thoughts about the move.'],['in theory / in practice','en théorie / en pratique','In theory it’s simple; in practice it isn’t.'],['brave','courageux','I wish I were braver.'],['Suppose… / Imagine…','Suppose que… / Imagine que…','Suppose you lost your job. What would you do?']],
  note:'<b>Attention :</b> <i lang="en">brave</i> veut dire « courageux », pas « brave » au sens de « gentil ». Et <i lang="en">savings</i> (les économies d’argent) ≠ <i lang="en">economy</i> (l’économie d’un pays).'},

 {kind:'Pratique', h:'Recall: afford',
  p:'Translate into English.<br>« Nous n’avons pas les moyens d’acheter une maison. »', lab:'Your sentence',
  txt:['We can’t afford to buy a house.','We cannot afford to buy a house.','We can’t afford a house.','We can’t afford to buy a home.'],
  why:'<i lang="en">We can’t afford to buy a house.</i> « avoir les moyens de » = <i lang="en">can afford to</i> + base verbale, presque toujours avec <i lang="en">can / can’t / could</i>.'},

 {kind:'Grammaire', h:'Le 2e conditionnel : if + prétérit, would',
  p:`<p>Sam dit : <i lang="en">If I had more savings, I’d go back to university.</i> Il n’a pas ces économies : il parle d’une situation <b>imaginaire</b>, contraire à la réalité présente. Pour cela, l’anglais utilise le <b>deuxième conditionnel</b>.</p>
<div class="def"><p><b>If + prétérit, would + base verbale.</b><br><i lang="en">If I <b>had</b> more time, I <b>would learn</b> Japanese.</i><br>On peut inverser les deux parties : <i lang="en">I would learn Japanese if I had more time</i> (sans virgule dans ce cas). <i lang="en">would</i> se contracte en <b>’d</b>, <i lang="en">would not</i> en <b>wouldn’t</b>. À la place de <i lang="en">would</i>, on peut mettre <b>could</b> (capacité : je pourrais) ou <b>might</b> (possibilité : je ferais peut-être).</p></div>
<div class="idea"><p>Le prétérit ne parle pas ici du passé : il marque la <b>distance avec la réalité</b>. Bonne nouvelle, c’est exactement le système français : « Si j’<b>avais</b> (imparfait)…, je <b>ferais</b> (conditionnel) ». Imparfait → prétérit, conditionnel → <i lang="en">would</i>.</p><p>Compare avec le premier conditionnel, vu en A2 : <i lang="en">If it rains tomorrow, we’ll stay at home</i> (c’est possible, réel). <i lang="en">If I lived in Spain, I’d eat outside every evening</i> (je n’y vis pas : imaginaire). Le choix dépend de la façon dont tu vois la situation : <i lang="en">If I win</i> = je peux gagner ; <i lang="en">If I won</i> = ça m’étonnerait.</p></div>
<div class="ex"><p><i lang="en">If she had a car, she could drive us.</i> = Si elle avait une voiture, elle pourrait nous conduire.<br><i lang="en">What would you do if you lost your job?</i><br><i lang="en">If we left now, we might catch the train.</i></p></div>
<div class="warn"><p>Jamais <b>would</b> dans la partie en <b>if</b> : « If I would have more money » est faux, comme « si j’aurais » en français. Et ne mélange pas les deux conditionnels : « If I had time, I will help you » est faux → <i lang="en">If I had time, I would help you</i>.</p></div>`,
  audio:'If I had more time, I would learn Japanese. If it rains tomorrow, we’ll stay at home. If I lived in Spain, I’d eat outside every evening.'},

 {kind:'Méthode', h:'Construire une phrase au 2e conditionnel',
  p:`<p><b>Quand :</b> pour parler d’une situation imaginaire ou très peu probable, maintenant ou dans le futur, et de sa conséquence. <b>Pourquoi ça marche :</b> chacune des deux parties de la phrase a son temps fixe ; si tu les construis séparément, tu ne peux pas te tromper. <b>Comment :</b></p>
<ol><li>Repère la <b>condition</b> imaginaire (« si j’avais… ») et la <b>conséquence</b> (« je ferais… »).</li><li>Condition : <b>if + sujet + prétérit</b> (irréguliers : <i lang="en">had, knew, could, went, spoke, lost</i>… ; pour <i lang="en">be</i> : <i lang="en">were</i>).</li><li>Conséquence : <b>sujet + would / could / might + base verbale</b>.</li><li>Vérifie qu’il n’y a <b>pas de would après if</b>, et mets une virgule si la phrase commence par <i lang="en">if</i>.</li></ol>`,
  demo:{enonce:'Traduis : (1) « Si je parlais japonais, je pourrais travailler à Tokyo. » (2) « Qu’est-ce que tu ferais si tu perdais ton passeport ? »',
   etapes:[{f:'(1) Condition : <i lang="en">If I spoke Japanese,</i>',w:'« parlais » (imparfait) → prétérit de <i lang="en">speak</i>, verbe irrégulier : <i lang="en">spoke</i>.'},
    {f:'Conséquence : <i lang="en">I could work in Tokyo.</i>',w:'« je pourrais » exprime une capacité : <i lang="en">could</i> + base verbale <i lang="en">work</i>.'},
    {f:'(2) Conséquence, en question : <i lang="en">What would you do</i>',w:'La question porte sur la conséquence : mot interrogatif + <i lang="en">would</i> + sujet + base verbale.'},
    {f:'Condition : <i lang="en">if you lost your passport?</i>',w:'« perdais » → prétérit de <i lang="en">lose</i> : <i lang="en">lost</i>. Pas de <i lang="en">would</i> après <i lang="en">if</i>.'}],
   conclusion:'<i lang="en">If I spoke Japanese, I could work in Tokyo. What would you do if you lost your passport?</i>'}},

 {kind:'Pratique', h:'Practice: build the sentence',
  p:'Write one sentence in the second conditional with these words: <i lang="en">I / have / more time / learn / Japanese</i>.', lab:'Your sentence',
  txt:V(['If I had more time, I would learn Japanese.','I would learn Japanese if I had more time.']),
  why:'<i lang="en">If I had more time, I’d learn Japanese.</i> Prétérit après <i lang="en">if</i> (<i lang="en">had</i>), <i lang="en">would</i> + base dans la conséquence.'},

 {kind:'Pratique', h:'Practice: a question',
  p:'Translate into English.<br>« Qu’est-ce que tu ferais si tu perdais ton téléphone ? »', lab:'Your question',
  txt:['What would you do if you lost your phone?','If you lost your phone, what would you do?','What would you do if you lost your mobile?','What would you do if you lost your mobile phone?'],
  why:'<i lang="en">What would you do if you lost your phone?</i> <i lang="en">lose</i> est irrégulier : <i lang="en">lost</i>. La question se forme avec <i lang="en">would</i> dans la conséquence, jamais dans la partie en <i lang="en">if</i>.'},

 {kind:'Pratique', h:'Practice: from real to imaginary',
  p:'Rewrite the sentence with <i lang="en">If</i>. Keep the same meaning.<br><i lang="en">I don’t have a car, so I can’t drive you to the airport.</i>', lab:'Your sentence', long:true,
  txt:V([...X('If I had a car, ',['I could drive you to the airport.','I would drive you to the airport.','I would be able to drive you to the airport.']),...X(['I could drive you','I would drive you','I would be able to drive you'],' to the airport if I had a car.')]),
  why:'<i lang="en">If I had a car, I could drive you to the airport.</i> La réalité est négative (je n’ai pas de voiture) : la phrase imaginaire est affirmative. <i lang="en">can’t</i> devient <i lang="en">could</i> (capacité).'},

 {kind:'Pratique', h:'Practice: real or imaginary?',
  p:'Complete with the correct form of the verb in brackets. Write one word only.<br><i lang="en">Don’t worry, I’m sure she’ll help you. If you ___ (ask) her, she’ll say yes.</i>', lab:'Missing word', txt:['ask'],
  why:'La situation est réelle et probable, et la conséquence est au futur (<i lang="en">she’ll say yes</i>) : c’est le <b>premier</b> conditionnel, avec le présent après <i lang="en">if</i> : <i lang="en">If you ask her</i>. Ne mets pas le prétérit partout dès que tu vois <i lang="en">if</i>.'},

 {kind:'Grammaire', h:'If I were you : donner un conseil',
  p:`<p>Lucy conseille Sam : <i lang="en">If I were you, I’d talk to your manager.</i> C’est la façon la plus courante de donner un conseil personnel en anglais : on s’imagine à la place de l’autre, ce qui est évidemment une situation irréelle, donc un deuxième conditionnel.</p>
<div class="def"><p><b>If I were you, I’d (I would) + base verbale</b> = À ta place, je…<br><b>If I were you, I wouldn’t + base verbale</b> = À ta place, je ne… pas.</p></div>
<div class="idea"><p>Dans la condition du deuxième conditionnel, <i lang="en">be</i> se met à <b>were</b> pour toutes les personnes : <i lang="en">if I were rich, if she were here, if it were up to me</i>. À l’oral, on entend souvent <i lang="en">if I was, if she was</i> : c’est accepté dans la langue courante, mais <i lang="en">were</i> est plus soigné, et dans l’expression figée <i lang="en">If I were you</i>, c’est la forme à retenir.</p></div>
<div class="ex"><p><i lang="en">If I were you, I’d take the job.</i> = À ta place, j’accepterais le poste.<br><i lang="en">If I were you, I wouldn’t lend him any money.</i><br><i lang="en">If it were up to me, we’d leave now.</i> = Si ça ne tenait qu’à moi, on partirait maintenant.</p></div>
<div class="warn"><p>« À ta place » ne se traduit pas mot à mot : <i lang="en">at your place</i> veut dire « chez toi »&nbsp;! On dit <i lang="en">If I were you</i> (ou, plus familier, <i lang="en">in your shoes</i>). Et ni « If I am you », ni « If I would be you ».</p></div>`,
  audio:'If I were you, I’d take the job. If I were you, I wouldn’t lend him any money. If it were up to me, we’d leave now.'},

 {kind:'Pratique', h:'Practice: give advice',
  p:'Your friend says: <i lang="en">My neighbours are so noisy every night!</i> Give advice. Translate into English with <i lang="en">If I were you</i>.<br>« À ta place, j’irais leur parler. »', lab:'Your advice',
  txt:V([...X(['If I were you, ','If I was you, '],'I would ',['go and talk to them.','go and speak to them.','go and have a word with them.','talk to them.','speak to them.','go to talk to them.','go to speak to them.']),...X('I would ',['go and talk to them','go and speak to them','talk to them','speak to them'],[' if I were you.',' if I was you.'])]),
  why:'<i lang="en">If I were you, I’d go and talk to them.</i> « aller faire » se dit souvent <i lang="en">go and do</i> en britannique. <i lang="en">If I was you</i> s’entend à l’oral, mais <i lang="en">were</i> est la forme soignée.'},

 {kind:'Grammaire', h:'I wish et if only : regretter le présent',
  p:`<p>Sam soupire : <i lang="en">I wish I didn’t have to work on Saturdays</i>, et plus tard <i lang="en">I wish I were braver</i>. Il travaille le samedi et ne se trouve pas courageux : il voudrait que la réalité présente soit différente. C’est encore une situation irréelle, et l’anglais emploie encore le prétérit.</p>
<div class="def"><p><b>I wish + sujet + prétérit</b> = je regrette que ce ne soit pas le cas, j’aimerais que ce soit différent (maintenant).<br><b>I wish I could + base verbale</b> = j’aimerais pouvoir.<br><b>If only + sujet + prétérit</b> = si seulement… (plus fort, plus émotif).</p></div>
<div class="idea"><p>La logique est la même qu’avec <i lang="en">if</i> : le prétérit marque la distance avec la réalité. <i lang="en">I wish I had a car</i> → je n’ai pas de voiture. <i lang="en">I wish I lived by the sea</i> → je n’y vis pas. <i lang="en">I wish I were taller</i> → je ne suis pas grand. Une phrase négative dit ce qui est vrai : <i lang="en">I wish I didn’t have to get up early</i> → je dois me lever tôt. Comme après <i lang="en">if</i>, <i lang="en">were</i> est la forme soignée (<i lang="en">was</i> à l’oral courant).</p></div>
<div class="ex"><p><i lang="en">I wish I knew the answer.</i> = J’aimerais bien connaître la réponse.<br><i lang="en">I wish I could come, but I’m working.</i> = J’aimerais pouvoir venir, mais je travaille.<br><i lang="en">If only we had more time!</i> = Si seulement nous avions plus de temps&nbsp;!</p></div>
<div class="warn"><p><b>wish</b> ou <b>hope</b>&nbsp;? <i lang="en">hope</i> parle d’une chose <b>possible</b>, avec un temps normal : <i lang="en">I hope you get the job</i> (j’espère que tu l’auras). <i lang="en">wish</i> parle d’une chose <b>irréelle</b>, au prétérit : <i lang="en">I wish I had a better job</i>. Pas de présent après <i lang="en">I wish</i> : « I wish I have » est faux. Enfin, <i lang="en">I wish you a happy birthday</i> (je te souhaite…) est une autre construction, suivie d’un nom.</p></div>`,
  audio:'I wish I knew the answer. I wish I could come, but I’m working. If only we had more time! I hope you get the job.'},

 {kind:'Pratique', h:'Practice: I wish',
  p:'You don’t speak Spanish, and you would like to. Write a sentence that starts with <i lang="en">I wish</i>.', lab:'Your sentence',
  txt:['I wish I spoke Spanish.','I wish I could speak Spanish.','I wish I knew Spanish.','I wish I were able to speak Spanish.','I wish I was able to speak Spanish.','I wish I spoke Spanish fluently.','I wish I could speak Spanish fluently.'],
  why:'<i lang="en">I wish I spoke Spanish</i> ou <i lang="en">I wish I could speak Spanish</i> : prétérit (ou <i lang="en">could</i>) après <i lang="en">I wish</i>, pour une réalité présente qu’on voudrait différente. « I wish I speak » est faux.'},

 {kind:'Pratique', h:'Practice: a regret about the present',
  p:'Put the words in the correct order.<br><b>Question:</b> how do you say « J’aimerais ne pas devoir travailler le samedi »?',
  ordre:['I','wish','I','didn’t','have','to','work','on','Saturdays.'],
  why:'<i lang="en">I wish I didn’t have to work on Saturdays.</i> La réalité : je dois travailler le samedi. Après <i lang="en">I wish</i>, la négation se fait au prétérit avec <i lang="en">didn’t</i>.'},

 {kind:'Pratique', h:'Practice: hope or wish?',
  p:'Complete with <i lang="en">hope</i> or <i lang="en">wish</i>. Write one word only.<br><i lang="en">Good luck tomorrow! I ___ you get the job.</i>', lab:'Missing word', txt:['hope'],
  why:'Obtenir le poste est tout à fait possible, et le verbe qui suit est au présent (<i lang="en">you get</i>) : <i lang="en">I hope you get the job</i>. <i lang="en">wish</i> + prétérit serait pour une situation irréelle.'},

 {kind:'Prononciation', h:'’d et would : les formes faibles',
  p:`<p><i lang="en">would</i> est rarement prononcé en entier. Si tu ne reconnais pas ses formes réduites, tu rates le sens imaginaire de la phrase.</p>
<div class="def"><ul><li>Après un pronom, <i lang="en">would</i> devient <b>’d</b> : <i lang="en">I’d</i> « aïd », <i lang="en">you’d</i> « youd », <i lang="en">she’d</i> « shiid », <i lang="en">we’d</i> « wiid », <i lang="en">they’d</i> « théïd ». Le d est très léger, presque inaudible devant une consonne : <i lang="en">I’d go</i>.</li><li>Dans une question, <i lang="en">would</i> s’affaiblit en « wəd » : <i lang="en">What would you do?</i> se dit presque « wot-wəd-jə-dou ».</li><li><i lang="en">wouldn’t</i> se dit « woud-nt », deux syllabes très serrées.</li></ul></div>
<div class="warn"><p>Le <b>l</b> de <i lang="en">would, could, should</i> ne se prononce jamais : <i lang="en">would</i> sonne exactement comme <i lang="en">wood</i> (le bois). Et le « ou » est court, comme dans <i lang="en">good</i>, pas long comme dans <i lang="en">food</i>. Attention aussi : <i lang="en">I’d</i> peut être <i lang="en">I had</i> (<i lang="en">I’d better go</i>) ; c’est le verbe qui suit qui tranche.</p></div>`,
  audio:'I’d go. You’d love it. She’d never agree. What would you do? I wouldn’t worry. Would, could, should.'},

 {kind:'Oral', h:'Repeat: a piece of advice',
  p:'This sentence is from the dialogue. Listen, then say it from memory. Contract <i lang="en">would</i> (<i lang="en">I’d</i>) and don’t pronounce the l. Stress: <i lang="en">If I were <b>you</b>, I’d <b>talk</b> to your <b>man</b>ager.</i>',
  dire:{t:'If I were you, I’d talk to your manager.', cache:true}},

 {kind:'Lecture', h:'If you could change one thing',
  p:`<p>Read this page from a magazine, then answer the question. You can also listen to it.</p>
<div class="blk" data-t="Readers’ page: one thing"><p lang="en">We asked our readers: if you could change one thing about your life, what would it be? Here are three of our favourite answers.</p><p lang="en"><b>Hannah, 34, nurse:</b> “I wish I lived closer to work. I spend nearly two hours a day on trains. If I had that time back, I’d sleep more, and I might even start running again.”</p><p lang="en"><b>Kofi, 19, student:</b> “Honestly? I wish I weren’t so shy. If I were more confident, I’d speak up in seminars instead of sitting at the back. My friends say I’d be a great teacher, but the idea of speaking in public terrifies me.”</p><p lang="en"><b>Margaret, 67, retired:</b> “Nothing big. I’d learn to play the piano. My mother always used to say, ‘If only you practised!’ She was right. If I could go back, I’d listen to her. Then again, it’s never too late, is it? I’ve just booked my first lesson.”</p></div>
<p><b>Question:</b> which reader has already done something to change her or his life?</p>`,
  audio:'We asked our readers: if you could change one thing about your life, what would it be? Here are three of our favourite answers. Hannah, 34, nurse: I wish I lived closer to work. I spend nearly two hours a day on trains. If I had that time back, I’d sleep more, and I might even start running again. Kofi, 19, student: Honestly? I wish I weren’t so shy. If I were more confident, I’d speak up in seminars instead of sitting at the back. My friends say I’d be a great teacher, but the idea of speaking in public terrifies me. Margaret, 67, retired: Nothing big. I’d learn to play the piano. My mother always used to say, If only you practised! She was right. If I could go back, I’d listen to her. Then again, it’s never too late, is it? I’ve just booked my first lesson.',
  opts:['Hannah','Kofi','Margaret','None of them'], ans:2,
  why:'Margaret termine par <i lang="en">I’ve just booked my first lesson</i> : elle vient de réserver son premier cours de piano. Hannah et Kofi ne font qu’imaginer (<i lang="en">I wish I lived…, If I were more confident, I’d…</i>).'},

 {kind:'Dictée', h:'Dictation: by the sea',
  p:'Listen and write the sentence exactly. You can listen as many times as you like.',
  dictee:'If we lived by the sea, we would go swimming every morning.',
  why:'Prétérit après <i lang="en">if</i> (<i lang="en">lived</i>), puis <i lang="en">would</i> + base (<i lang="en">would go</i>). Attention à <i lang="en">swimming</i> (deux m) et à la préposition : <i lang="en">by the sea</i> = au bord de la mer.'},

 {kind:'Oral', h:'A year off',
  p:`<p>Speak for 45 seconds to one minute: <i lang="en">What would you do if you didn’t have to work or study for a whole year?</i> Say at least three things you would do, use <i lang="en">could</i> or <i lang="en">might</i> once, and say one thing you wish. Tap « Parler », then « J’ai fini ».</p>`,
  oral:{modele:'If I didn’t have to work for a year, I’d travel slowly around South America. I’d start in Mexico and take buses all the way down to Argentina. I’d learn Spanish properly, because I wish I could speak it fluently. I might also work on a farm for a few weeks. Of course, I’d miss my friends, and I’d need a lot of savings, but it would be a dream come true.',
   criteres:['I used the second conditional (If I didn’t have to…, I’d…)','I said at least three things I would do','I used could or might at least once','I used I wish once','I mentioned a problem or a reason (but, because…)']}},

 {kind:'Écriture', h:'Write: anywhere in the world',
  p:'A travel website asks: <i lang="en">If you could live anywhere in the world for one year, where would you go, and why?</i> Write your answer (about 120 words). Give at least two reasons, mention one problem, use the second conditional several times and <i lang="en">I wish</i> once, and end with a question to the reader.',
  ecrire:{min:100, modele:'If I could live anywhere for a year, I would choose Vancouver, in Canada. First, I love nature, and the city is between the ocean and the mountains. If I lived there, I would go hiking every weekend, and I might even learn to ski. I would rent a small flat near the beach and take the ferry to the islands. Second, my English would improve a lot, because I would speak it every day. Of course, it wouldn’t be perfect: rents are very high, and I would miss my family. I wish Canada were closer to Switzerland! But if I had the chance, I wouldn’t hesitate for a second. What about you? Where would you go if you could choose?',
   criteres:[{t:'I used if + past simple', re:'\\bif (i|you|he|she|we|they|it) (had|were|was|lived|could|knew|went|spoke|didn[’\']t|\\w+ed)\\b'},{t:'I used would or ’d', re:'\\b(would|wouldn[’\']t)\\b|[’\']d\\b'},{t:'I used could or might', re:'\\b(could|might)\\b'},{t:'I used I wish or If only', re:'\\b(i wish|if only)\\b'},'I gave at least two reasons and one problem',{t:'I ended with a question', re:'\\?'}]}},

 {kind:'Récapitulatif', h:'Ce qu’il faut retenir',
  p:`<div class="keep"><ul><li><b>2e conditionnel</b> : <i lang="en">If + prétérit, would / could / might + base</i>, pour une situation imaginaire ou très improbable (<i lang="en">If I had more time, I’d learn Japanese</i>). Comme en français : « si + imparfait, conditionnel ».</li><li>Jamais <i lang="en">would</i> après <i lang="en">if</i>. Virgule quand la phrase commence par <i lang="en">if</i>.</li><li><b>1er ou 2e</b> : <i lang="en">If you ask her, she’ll say yes</i> (réel, possible) / <i lang="en">If I won the lottery, I’d buy an island</i> (imaginaire).</li><li><b>If I were you, I’d… / I wouldn’t…</b> = à ta place. <i lang="en">were</i> pour toutes les personnes (<i lang="en">was</i> à l’oral courant). Jamais « at your place ».</li><li><b>I wish + prétérit</b> (<i lang="en">I wish I had…, I wish I were…, I wish I didn’t have to…</i>), <b>I wish I could…</b>, <b>If only…</b> : regretter le présent.</li><li><b>hope</b> pour le possible (<i lang="en">I hope you get the job</i>), <b>wish</b> pour l’irréel.</li><li>Prononciation : <i lang="en">I’d</i> « aïd », <i lang="en">would</i> = <i lang="en">wood</i> (l muet), forme faible « wəd » dans les questions.</li></ul></div>`},

 {kind:'Mission', h:'Ask Anna',
  p:'You are listening to a radio advice programme. Listen to the call, then answer the questions one by one. You can listen again at any time.',
  audio:[['Anna','You’re listening to Ask Anna. Our next caller is Megan. Hi, Megan, what’s on your mind?'],['Megan','Hi, Anna. I’ve been offered a job in Canada. It’s a great position, but my boyfriend doesn’t want to leave his family here.'],['Anna','I see. And what would you do if he weren’t part of the picture?'],['Megan','Oh, I’d go tomorrow! It’s my dream job.'],['Anna','Then, honestly, if I were you, I’d sit down with him and talk about it properly. Would he consider going for a year, as a trial?'],['Megan','I don’t know. To be honest, I wish he were more adventurous.'],['Anna','Well, if you didn’t ask him, you’d never know. And if you turned the job down, would you regret it?'],['Megan','Probably, yes. Every day.'],['Anna','Then I think you already have your answer.']], cache:true,
  parts:[
   {q:'a) What is Megan’s problem?', opts:['She has lost her job in Canada.','Her boyfriend wants to move to Canada without her.','She has been offered a job in Canada, but her boyfriend doesn’t want to leave.','She doesn’t like her new job.'], ans:2, hint:'Listen to Megan’s first answer.', why:'<i lang="en">I’ve been offered a job in Canada… but my boyfriend doesn’t want to leave his family here.</i>'},
   {q:'b) Complete Anna’s advice with two words: <i lang="en">If I were you, I’d ___ ___ with him and talk about it properly.</i>', lab:'Missing words', txt:['sit down'], hint:'It means « s’asseoir ».', why:'<i lang="en">If I were you, I’d sit down with him and talk about it properly.</i> Le conseil typique : <i lang="en">If I were you, I’d</i> + base verbale.'},
   {q:'c) Megan would like her boyfriend to be more adventurous. Write her sentence with <i lang="en">I wish</i>.', lab:'Her sentence', txt:['I wish he were more adventurous.','I wish he was more adventurous.'], hint:'After <i lang="en">I wish</i>, the verb <i lang="en">be</i> goes into the past: which form?', why:'<i lang="en">I wish he were more adventurous</i> (ou, à l’oral courant, <i lang="en">was</i>). La réalité : il n’est pas très aventureux.'},
   {q:'d) Give Megan your own advice. Translate: « À ta place, j’accepterais le poste. »', lab:'Your advice', txt:V([...X(['If I were you, ','If I was you, '],'I would ',['accept','take'],' the ',['job.','position.','offer.','job offer.']),...X('I would ',['accept','take'],' the ',['job','position','offer'],' if I were you.')]), hint:'« À ta place » = <i lang="en">If I were you</i>, then <i lang="en">would</i> + base verb.', why:'<i lang="en">If I were you, I’d take the job</i> (ou <i lang="en">accept the job</i>). Et si tu pensais le contraire : <i lang="en">If I were you, I wouldn’t take it.</i>'}],
  sol:'<p lang="en">Megan has been offered a job in Canada, but her boyfriend doesn’t want to leave his family. If he weren’t part of the picture, she’d go tomorrow. Anna’s advice: if I were you, I’d sit down with him and talk about it properly.</p><p>Megan regrette le caractère de son ami : <i lang="en">I wish he were more adventurous</i>. Anna lui fait remarquer que si elle refusait le poste (<i lang="en">if you turned the job down</i>), elle le regretterait. Ton conseil : <i lang="en">If I were you, I’d take the job.</i></p>'},

 {kind:'Mission', h:'Leo’s dilemma',
  p:`<p>Your friend Leo has sent you this message. Read it, then answer the questions.</p>
<div class="blk" data-t="Message from Leo"><p lang="en">Hi! I need your advice. You know I’ve been renting a tiny flat in the city centre for six years. Now a friend is selling her cottage in a village forty minutes away, and it’s really cheap. The problem is that I don’t drive, the last bus leaves at 7 p.m., and I’d be far from all my friends. But I can’t afford a bigger place in town, and I’m tired of hearing my neighbours through the wall every night. Part of me says: go for it! The other part is having second thoughts. What would you do? Leo</p></div>`,
  parts:[
   {q:'a) Why is Leo having second thoughts?', opts:['The cottage is too expensive.','He doesn’t drive, the buses stop early and he would be far from his friends.','His friend doesn’t want to sell the cottage.','He loves his flat in the city centre.'], ans:1, hint:'Look at the sentence that starts with <i lang="en">The problem is…</i>', why:'<i lang="en">I don’t drive, the last bus leaves at 7 p.m., and I’d be far from all my friends.</i> Le cottage, lui, est bon marché.'},
   {q:'b) Leo doesn’t drive. Write what he could say, starting with <i lang="en">I wish</i>.', lab:'His sentence', txt:['I wish I could drive.','I wish I drove.','I wish I knew how to drive.','I wish I had a driving licence.','I wish I had a driver’s license.','I wish I was able to drive.','I wish I were able to drive.'], hint:'Ability: <i lang="en">I wish I could…</i>', why:'<i lang="en">I wish I could drive</i> (j’aimerais savoir conduire), ou <i lang="en">I wish I had a driving licence</i>. Jamais « I wish I can drive ».'},
   {q:'c) Write one sentence in the second conditional with these words: <i lang="en">Leo / buy the cottage / be far from his friends</i>.', lab:'Your sentence', long:true, txt:V(['If Leo bought the cottage, he would be far from his friends.','Leo would be far from his friends if he bought the cottage.','If he bought the cottage, he would be far from his friends.','If Leo bought the cottage, he would be a long way from his friends.']), hint:'<i lang="en">buy</i> is irregular: what is its past simple?', why:'<i lang="en">If Leo bought the cottage, he’d be far from his friends.</i> Prétérit irrégulier <i lang="en">bought</i> après <i lang="en">if</i>, puis <i lang="en">would be</i>.'},
   {q:'d) Reply to Leo. Translate: « À ta place, je n’achèterais pas le cottage tout de suite. »', lab:'Your advice', long:true, txt:V([...X(['If I were you, ','If I was you, '],'I would not buy the cottage ',['straight away.','right away.','immediately.','yet.','right now.']),...X('I would not buy the cottage ',['straight away','right away','immediately','yet','right now'],' if I were you.')]), hint:'Negative advice: <i lang="en">If I were you, I wouldn’t…</i>', why:'<i lang="en">If I were you, I wouldn’t buy the cottage straight away.</i> On pourrait ajouter une solution : <i lang="en">I’d rent a room in the village first, to see if I liked it.</i>'}],
  sol:'<p>Leo hésite (<i lang="en">he’s having second thoughts</i>) : le cottage est bon marché, mais il ne conduit pas, le dernier bus part à 19 h et il serait loin de ses amis (<i lang="en">I’d be far from all my friends</i>). Phrases attendues : <i lang="en">I wish I could drive.</i> <i lang="en">If Leo bought the cottage, he’d be far from his friends.</i> <i lang="en">If I were you, I wouldn’t buy the cottage straight away.</i> Tous ces énoncés décrivent des situations irréelles : prétérit après <i lang="en">if</i> et <i lang="en">wish</i>, <i lang="en">would</i> dans la conséquence.</p>'},
]},
);
})();
